             <p className="text-[0.6rem] font-black text-gray-400 uppercase tracking-widest">Step {step + 1} of {STEPS.length}</p>
          </div>

          <div className="flex gap-2">
             {STEPS.map((s, i) => (<div key={i} className={`h-1.5 rounded-full flex-1 transition-all duration-500 ${i === step ? 'bg-primary-500 shadow-[0_0_10px_rgba(16,185,129,0.4)]' : i < step ? 'bg-primary-500/30' : 'bg-gray-200 dark:bg-white/10'}`}></div>))}
          </div>
       </div>

       <div className="flex-1 overflow-y-auto p-8 no-scrollbar">
          {step === 0 && renderStepVehicle()}
          {step === 1 && renderStepCoverage()}
          {step === 2 && renderStepProviders()}
          {step === 3 && renderStepKYC()}
          {step === 4 && renderStepPreSummary()}
          {step === 5 && renderStepSurvey()}
          {step === 6 && renderStepFinal()}
       </div>

       <div className="px-8 py-6 bg-white dark:bg-[#111] border-t border-black/5 flex items-center justify-between gap-6 flex-shrink-0 sticky bottom-0 z-[100] shadow-[0_-10px_30px_rgba(0,0,0,0.05)]">
          <div className="flex-1">
             <p className="text-[0.55rem] font-black uppercase text-gray-400 leading-none mb-1 tracking-widest">Est. Premium</p>
             <p className="text-2xl font-black tracking-tighter text-primary-500">{premiumBreakdown ? formatIDR(premiumBreakdown.totalPayable) : 'Rp 0'}</p>
          </div>
          <div className="flex gap-3">
             {step > 0 && (<button onClick={handleBack} className="p-4 bg-gray-100 dark:bg-white/10 rounded-2xl text-gray-500 hover:text-primary-500 transition-colors shadow-sm"><ChevronLeft size={24}/></button>)}
             {step < STEPS.length - 1 && (
                <button 
                  onClick={handleNext} 
                  disabled={(step === 5 && survey.score === 0)}
                  className="px-10 py-4 bg-gray-900 dark:bg-white text-white dark:text-black rounded-2xl font-black uppercase text-[0.7rem] tracking-[0.2em] shadow-2xl transition-all active:scale-95 flex items-center gap-2 disabled:opacity-30 disabled:grayscale"
                >
                  {step === 5 && survey.manualVerif ? 'Submisi HQ' : 'Lanjut'} <ChevronRight size={18}/>
                </button>
             )}
          </div>
       </div>
    </div>
  );
};

