                           <span className="text-[0.5rem] font-black uppercase tracking-widest">{item.label}</span>
                        </div>
                        <p className={`text-[0.8rem] font-black uppercase tracking-tight truncate ${item.color || 'text-gray-900 dark:text-white'}`}>{item.value}</p>
                    </div>
                ))}
             </div>

             <div className="pt-6 border-t border-black/5 dark:border-white/5 flex justify-between items-center">
                <div>
                    <p className="text-[0.55rem] font-black uppercase text-gray-400">Total Premi</p>
                    <p className="text-2xl font-black text-primary-500 tracking-tighter">{premiumBreakdown ? formatIDR(premiumBreakdown.totalPayable) : 'Rp 0'}</p>
                </div>
                <div className="p-4 bg-gray-50 dark:bg-black/20 rounded-2xl border border-black/5">
                   <Shield size={24} className="text-primary-500"/>
                </div>
             </div>
          </div>

          {survey.verdict !== 'REJECTED' && (
            <button onClick={() => { clearProgress(); onComplete(); }} className="w-full py-6 bg-gray-900 dark:bg-white text-white dark:text-black rounded-[2rem] font-black uppercase text-base tracking-[0.25em] shadow-2xl flex items-center justify-center gap-4 transition-all hover:scale-[1.02] active:scale-95">
               <Wallet size={24} className="text-primary-500"/> KONFIRMASI PEMBAYARAN
            </button>
          )}
        </div>
      );
  };

  return (
    <div className="flex flex-col h-full min-h-screen bg-slate-50 dark:bg-dark-bg text-gray-900 dark:text-white overflow-hidden relative">
       <div className="px-8 pt-8 pb-4 bg-white dark:bg-white/5 border-b border-black/5 flex flex-col gap-6 flex-shrink-0 relative z-[100]">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
               <div className="w-12 h-12 bg-primary-500 rounded-2xl flex items-center justify-center text-white shadow-xl shadow-primary-500/20 group"><Car size={24} className="group-hover:rotate-12 transition-transform"/></div>
               <div>
                  <p className="text-[0.45rem] font-black text-gray-400 uppercase tracking-[0.4em] leading-none mb-1">Matrix Auto</p>
                  <h3 className="text-lg font-black uppercase tracking-tighter">Insurance Matrix</h3>
               </div>
            </div>
            <div className="flex items-center gap-2">
               <button 
                onClick={() => { if(confirm("Restart progress?")) { clearProgress(); window.location.reload(); } }} 
                className="p-2.5 text-gray-400 hover:text-rose-500 bg-gray-100 dark:bg-white/10 rounded-xl transition-colors"
               >
                  <RefreshCw size={18}/>
               </button>
               <button onClick={onComplete} className="p-2.5 text-gray-400 hover:text-gray-900 dark:hover:text-white bg-gray-100 dark:bg-white/10 rounded-xl transition-colors">
                 <X size={20}/>
               </button>
            </div>
          </div>

          <div className="flex items-center justify-between">
             <div className="flex bg-gray-100 dark:bg-white/5 p-1 rounded-xl">
                <div className="px-3 py-1 text-[0.6rem] font-black text-primary-500 uppercase tracking-widest">{STEPS[step].label}</div>
             </div>
             <p className="text-[0.6rem] font-black text-gray-400 uppercase tracking-widest">Step {step + 1} of {STEPS.length}</p>
          </div>

          <div className="flex gap-2">
             {STEPS.map((s, i) => (<div key={i} className={`h-1.5 rounded-full flex-1 transition-all duration-500 ${i === step ? 'bg-primary-500 shadow-[0_0_10px_rgba(16,185,129,0.4)]' : i < step ? 'bg-primary-500/30' : 'bg-gray-200 dark:bg-white/10'}`}></div>))}
          </div>
       </div>

       <div className="flex-1 overflow-y-auto p-8 no-scrollbar">
          {step === 0 && renderStepVehicle()}
          {step === 1 && renderStepCoverage()}
          {step === 2 && renderStepProviders()}
          {step === 3 && renderStepKYC()}
          {step === 4 && renderStepPreSummary()}
          {step === 5 && renderStepSurvey()}
          {step === 6 && renderStepFinal()}
       </div>

       <div className="px-8 py-6 bg-white dark:bg-[#111] border-t border-black/5 flex items-center justify-between gap-6 flex-shrink-0 sticky bottom-0 z-[100] shadow-[0_-10px_30px_rgba(0,0,0,0.05)]">
          <div className="flex-1">
             <p className="text-[0.55rem] font-black uppercase text-gray-400 leading-none mb-1 tracking-widest">Est. Premium</p>
             <p className="text-2xl font-black tracking-tighter text-primary-500">{premiumBreakdown ? formatIDR(premiumBreakdown.totalPayable) : 'Rp 0'}</p>
          </div>
          <div className="flex gap-3">
             {step > 0 && (<button onClick={handleBack} className="p-4 bg-gray-100 dark:bg-white/10 rounded-2xl text-gray-500 hover:text-primary-500 transition-colors shadow-sm"><ChevronLeft size={24}/></button>)}
             {step < STEPS.length - 1 && (
                <button 
                  onClick={handleNext} 
                  disabled={(step === 5 && survey.score === 0)}
                  className="px-10 py-4 bg-gray-900 dark:bg-white text-white dark:text-black rounded-2xl font-black uppercase text-[0.7rem] tracking-[0.2em] shadow-2xl transition-all active:scale-95 flex items-center gap-2 disabled:opacity-30 disabled:grayscale"
                >
                  {step === 5 && survey.manualVerif ? 'Submisi HQ' : 'Lanjut'} <ChevronRight size={18}/>
                </button>
             )}
          </div>
       </div>
    </div>
  );
};

