            </div>
          </div>
        </div>
      ))}

      {/* Navigation Indicators */}
      <div className="absolute top-10 right-10 flex flex-col gap-3 z-20 bg-black/40 backdrop-blur-xl p-4 rounded-[2.5rem] border border-white/10 shadow-2xl">
        {SLIDES.map((_, i) => (
          <button 
            key={i} 
            onClick={() => setCurrent(i)}
            className={`transition-all duration-700 ease-out rounded-full ${i === current ? 'h-10 w-2 bg-primary-500 shadow-[0_0_15px_#10b981]' : 'h-2 w-2 bg-white/20'}`}
          />
        ))}
      </div>
    </div>
  );
};

