const AuthGate: React.FC<AuthGateProps> = ({ onAuthSuccess, initialLang = Language.EN }) => {
  const [mode, setMode] = useState<'LOGIN' | 'PARTNER' | 'REGISTER' | 'DASHBOARD' | 'VERIFY'>('LOGIN');
  const [lang, setLang] = useState<Language>(initialLang);
  const [showPass, setShowPass] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [logIdx, setLogIdx] = useState(0);
  const [verificationMethod, setVerificationMethod] = useState<'WHATSAPP' | 'EMAIL'>('WHATSAPP');
  const [otp, setOtp] = useState('');
  const [generatedOtp, setGeneratedOtp] = useState('');
  const [showIncomingSim, setShowIncomingSim] = useState(false);

  const [formData, setFormData] = useState({
    name: '',
    email: '', 
    phone: '',
    password: '',
    role: 'MEMBER'
  });

  const logs = [
    "PROTOCOL: ZERO-TRUST-KERNEL",
    "ENCRYPTION: AES-256-GCM READY",
    "NODE: JAKARTA-CENTER-S01",
    "ID-SYNC: BIOMETRIC-LINK-STABLE"
  ];

  useEffect(() => {
    const timer = setInterval(() => setLogIdx(i => (i + 1) % logs.length), 3000);
    return () => clearInterval(timer);
  }, []);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setTimeout(() => {
      const registry = JSON.parse(localStorage.getItem('SUREPATH_REGISTRY') || '[]');
      const user = registry.find((u: any) => (u.email === formData.email || u.nodeId === formData.email) && u.password === formData.password);
      if (user) {
        onAuthSuccess(user);
      } else if (formData.email === 'admin@surepath.ai' && formData.password === 'admin123') {
        onAuthSuccess({ name: 'Admin HQ', role: 'HQ', nodeId: 'SP-HQ-001', email: 'admin@surepath.ai' });
      } else {
        setLoading(false);
        setError("Neural ID mismatch. Decryption failed.");
      }
    }, 2000);
  };

  const handleRegisterStart = (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    const newOtp = Math.floor(100000 + Math.random() * 900000).toString();
    setGeneratedOtp(newOtp);
    setTimeout(() => {
      setLoading(false);
      setMode('VERIFY');
      setTimeout(() => setShowIncomingSim(true), 1500);
    }, 1500);
  };

  const handleVerifyFinal = () => {
    if (otp !== generatedOtp) {
      setError("Token sequence invalid. Access denied.");
      return;
    }
    setLoading(true);
    setTimeout(() => {
      const registry = JSON.parse(localStorage.getItem('SUREPATH_REGISTRY') || '[]');
      const newUser = { ...formData, nodeId: `SP-${Math.floor(Math.random()*9999)}`, memberSince: new Date().toLocaleDateString(), trustScore: 90, verified: true };
      registry.push(newUser);
      localStorage.setItem('SUREPATH_REGISTRY', JSON.stringify(registry));
      onAuthSuccess(newUser);
    }, 2500);
  };

  return (
    <div className="min-h-screen bg-midnight flex flex-col items-center justify-center p-6 relative overflow-hidden">

      {/* BACKGROUND EFFECTS */}
      <div className="absolute inset-0 bg-neural-grid opacity-20"></div>
      <div className="absolute top-[-20%] right-[-10%] w-[800px] h-[800px] bg-primary-500/10 rounded-full blur-[160px] animate-blob"></div>
      <div className="absolute bottom-[-10%] left-[-10%] w-[600px] h-[600px] bg-blue-500/10 rounded-full blur-[140px] animate-blob animation-delay-4000"></div>

      {showIncomingSim && (
        <div className="fixed top-10 left-1/2 -translate-x-1/2 z-[200] w-full max-w-sm px-4 animate-pop-in">
           <div className="bg-white/10 backdrop-blur-2xl border border-white/20 rounded-[3rem] p-8 shadow-2xl flex items-start gap-5 relative overflow-hidden group">
              <div className="w-14 h-14 bg-emerald-500 rounded-2xl flex items-center justify-center text-white flex-shrink-0 animate-bounce shadow-xl">
                 <BellRing size={28}/>
              </div>
              <div className="flex-1 space-y-2">
                 <p className="text-[0.65rem] font-black text-emerald-400 uppercase tracking-widest">Neural Notification</p>
                 <p className="text-sm font-bold text-white">Registry ID Secure Link:</p>
                 <p className="text-lg font-black text-white tracking-[0.2em]">{generatedOtp}</p>
                 <button onClick={() => setShowIncomingSim(false)} className="text-[0.6rem] font-black text-gray-500 uppercase tracking-widest mt-2 hover:text-white transition-colors flex items-center gap-1"><XIcon size={12}/> Dismiss</button>
              </div>
           </div>
        </div>
      )}

      <div className="w-full max-w-lg relative z-10 space-y-12">
        <div className="flex flex-col items-center gap-6">
          <SurePathLogo className="w-24 h-24 relative animate-hologram drop-shadow-[0_0_30px_rgba(16,185,129,0.3)]" />
          <div className="text-center">
            <h1 className="text-5xl font-black tracking-tighter uppercase text-white leading-none">
              Sure<span className="text-primary-500">Path</span>
            </h1>
            <p className="text-[0.7rem] font-black text-gray-500 uppercase tracking-[0.6em] mt-3 opacity-50">Portal Access Node</p>
          </div>
        </div>

        <div className="glass-card rounded-[4rem] p-10 lg:p-14 border border-white/10 shadow-[0_50px_100px_-20px_rgba(0,0,0,0.5)] bg-black/40 backdrop-blur-3xl relative overflow-hidden">
          {loading && (
            <div className="absolute inset-0 bg-black/95 backdrop-blur-3xl z-50 flex flex-col items-center justify-center gap-8 animate-fade-in">
               <div className="p-12 bg-white/5 rounded-[4rem] border border-white/10 shadow-2xl relative">
                  <Fingerprint className="text-primary-500 animate-pulse" size={100} />
                  <div className="absolute inset-0 border-2 border-primary-500/20 rounded-[4rem] animate-ping"></div>
               </div>
               <div className="text-center space-y-2">
                  <p className="text-[0.9rem] font-black text-white uppercase tracking-[0.6em] animate-pulse">Decrypting Identity</p>
                  <p className="text-[0.55rem] font-mono text-gray-500 uppercase tracking-widest">Protocol: Neural-Gate-S01</p>
               </div>
            </div>
          )}

          {mode === 'VERIFY' ? (
            <div className="space-y-10 animate-fade-in text-center">
                <div className="space-y-4">
                    <div className="w-24 h-24 bg-emerald-500/10 rounded-[2.5rem] flex items-center justify-center text-emerald-500 mx-auto border border-emerald-500/20 shadow-inner">
                        <Smartphone size={44}/>
                    </div>
                    <h3 className="text-3xl font-black text-white uppercase tracking-tighter">Neural Verification</h3>
                    <p className="text-[0.7rem] font-bold text-gray-500 uppercase tracking-widest leading-relaxed">
                        Input the 6-digit sequence dispatched via <span className="text-emerald-500">{verificationMethod}</span>
                    </p>
                </div>

                <div className="space-y-4">
                    <input 
                      maxLength={6}
                      placeholder="000000"
                      className="w-full py-8 bg-white/5 border-2 border-emerald-500/20 rounded-[3rem] text-center text-5xl font-black tracking-[0.5em] text-emerald-400 outline-none focus:border-emerald-500 transition-all placeholder:opacity-10"
                      value={otp}
                      onChange={(e) => {
                        setOtp(e.target.value.replace(/\D/g, ''));
                        setError(null);
                      }}
                    />
                    {error && <p className="text-[0.6rem] font-black text-rose-500 uppercase tracking-widest animate-shake">{error}</p>}
                </div>

                <button 
                  onClick={handleVerifyFinal}
                  disabled={otp.length < 6}
                  className="w-full py-7 bg-primary-500 text-white rounded-[2.5rem] font-black uppercase text-sm tracking-[0.4em] shadow-[0_20px_50px_rgba(16,185,129,0.3)] disabled:opacity-30 active:scale-95 transition-all"
                >
                  Verify & Decrypt
                </button>
                <button onClick={() => setMode('REGISTER')} className="text-[0.6rem] font-black text-gray-600 uppercase tracking-widest hover:text-white transition-colors">Resubmit Identity</button>
            </div>
          ) : (
            <>
                <div className="flex bg-white/5 p-2 rounded-[2.5rem] mb-12 border border-white/5 gap-2">
                    {[
                      { id: 'LOGIN', label: 'Access Gate', icon: Lock },
                      { id: 'REGISTER', label: 'Enroll Node', icon: UserPlusIcon }
                    ].map((m) => (
                    <button 
                        key={m.id}
                        onClick={() => { setMode(m.id as any); setError(null); }}
                        className={`flex-1 py-5 rounded-[2rem] text-[0.65rem] font-black uppercase tracking-widest transition-all duration-700 flex items-center justify-center gap-3 ${mode === m.id || (mode === 'LOGIN' && m.id === 'LOGIN') ? 'bg-white text-midnight shadow-2xl' : 'text-gray-500 hover:text-gray-300'}`}
                    >
                        <m.icon size={18}/> {m.label}
                    </button>
                    ))}
                </div>

                <form onSubmit={mode === 'REGISTER' ? handleRegisterStart : handleLogin} className="space-y-10">
                    {mode === 'REGISTER' ? (
                      <>
                        <InputField icon={User} label="Identity Name" type="text" name="name" placeholder="Full Legal Name" value={formData.name} onChange={(n:any, v:any)=>setFormData(f=>({...f,name:v}))} colorClass="text-primary-500" />
                        <InputField icon={Phone} label="Mobile Node" type="tel" name="phone" placeholder="+62 812 XXXX" value={formData.phone} onChange={(n:any, v:any)=>setFormData(f=>({...f,phone:v}))} colorClass="text-primary-500" />
                        <div className="space-y-4">
                           <p className="text-[0.6rem] font-black text-gray-500 uppercase tracking-[0.3em] ml-5">Verification Link</p>
                           <div className="grid grid-cols-2 gap-3">
                              <button type="button" onClick={()=>setVerificationMethod('WHATSAPP')} className={`py-4 rounded-2xl border-2 font-black text-[0.6rem] uppercase tracking-widest transition-all ${verificationMethod === 'WHATSAPP' ? 'border-primary-500 text-primary-500 bg-primary-500/5' : 'border-white/5 text-gray-600'}`}>WhatsApp</button>
                              <button type="button" onClick={()=>setVerificationMethod('EMAIL')} className={`py-4 rounded-2xl border-2 font-black text-[0.6rem] uppercase tracking-widest transition-all ${verificationMethod === 'EMAIL' ? 'border-primary-500 text-primary-500 bg-primary-500/5' : 'border-white/5 text-gray-600'}`}>Email Hub</button>
                           </div>
                        </div>
                      </>
                    ) : null}

                    <InputField 
                        icon={Mail} label="Neural ID / Registry" type="text" name="email" placeholder="node-identifier@surepath.ai" value={formData.email} onChange={(n:any, v:any)=>setFormData(f=>({...f,email:v}))} colorClass="text-primary-500"
                    />

                    <InputField 
                        icon={Lock} label="Access Key" type="password" name="password" placeholder="••••••••" value={formData.password} onChange={(n:any, v:any)=>setFormData(f=>({...f,password:v}))} showPass={showPass} setShowPass={setShowPass} colorClass="text-primary-500"
                    />

                    {error && <p className="text-[0.6rem] font-black text-rose-500 uppercase tracking-widest text-center">{error}</p>}

                    <button type="submit" className="w-full py-8 bg-midnight text-white rounded-[3rem] font-black uppercase text-sm tracking-[0.4em] shadow-2xl flex items-center justify-center gap-6 transition-all hover:bg-primary-500 active:scale-95 group border border-white/10">
                        {mode === 'REGISTER' ? 'Request Decryption' : 'Authorize Path'}
                        <ArrowRight size={24} className="group-hover:translate-x-3 transition-transform"/>
                    </button>
                </form>
            </>
          )}

          <div className="mt-16 pt-10 border-t border-white/5">
             <div className="flex items-center justify-center gap-4 py-4 bg-white/[0.02] rounded-3xl border border-white/5">
                <Terminal size={14} className="text-gray-600"/>
                <p className="text-[0.6rem] font-mono text-gray-500 uppercase tracking-widest animate-pulse">
                    {logs[logIdx]}
                </p>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

