const AuthGate: React.FC<AuthGateProps> = ({ onAuthSuccess, initialLang = Language.EN }) => {
  const [mode, setMode] = useState<'LOGIN' | 'REGISTER' | 'VERIFY'>('LOGIN');
  const [showPass, setShowPass] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [logIdx, setLogIdx] = useState(0);
  const [otp, setOtp] = useState('');
  const [generatedOtp, setGeneratedOtp] = useState('');
  const [showIncomingSim, setShowIncomingSim] = useState(false);

  const [formData, setFormData] = useState({
    name: '',
    email: '', 
    phone: '',
    password: '',
    role: UserRole.CUSTOMER
  });

  const logs = [
    "SESSION: INITIALIZING KERNEL...",
    "HANDSHAKE: RSA-4096 VALIDATED",
    "NODE: JKT-S01 SIGNAL STABLE",
    "PROTOCOL: ZERO-TRUST ENABLED"
  ];

  useEffect(() => {
    const timer = setInterval(() => setLogIdx(i => (i + 1) % logs.length), 2500);
    return () => clearInterval(timer);
  }, []);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    setTimeout(() => {
      // Demo logic for specific emails to trigger roles
      if (formData.email === 'master@surepath.ai' && formData.password === 'admin123') {
        onAuthSuccess({ name: 'Master Architect', role: UserRole.MASTER_ADMIN, nodeId: 'SP-HQ-000', email: 'master@surepath.ai' });
      } else if (formData.email === 'admin@surepath.ai' && formData.password === 'admin123') {
        onAuthSuccess({ name: 'Biz Admin', role: UserRole.ADMIN, nodeId: 'SP-HQ-001', email: 'admin@surepath.ai' });
      } else if (formData.email === 'finance@surepath.ai' && formData.password === 'admin123') {
        onAuthSuccess({ name: 'Finance Lead', role: UserRole.FINANCE, nodeId: 'SP-HQ-002', email: 'finance@surepath.ai' });
      } else if (formData.email === 'agent@surepath.ai' && formData.password === 'admin123') {
        onAuthSuccess({ name: 'Platinum Agent', role: UserRole.AGENT, nodeId: 'SP-AGENT-77', email: 'agent@surepath.ai' });
      } else {
        const registry = JSON.parse(localStorage.getItem('SUREPATH_REGISTRY') || '[]');
        const user = registry.find((u: any) => (u.email === formData.email || u.nodeId === formData.email) && u.password === formData.password);
        if (user) {
          onAuthSuccess(user);
        } else {
          setLoading(false);
          setError("NEURAL ID MISMATCH: ACCESS TERMINATED");
        }
      }
    }, 2000);
  };

  const handleRegisterStart = (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    const newOtp = Math.floor(100000 + Math.random() * 900000).toString();
    setGeneratedOtp(newOtp);
    setTimeout(() => {
      setLoading(false);
      setMode('VERIFY');
      setTimeout(() => setShowIncomingSim(true), 1200);
    }, 1800);
  };

  const handleVerifyFinal = () => {
    if (otp !== generatedOtp) {
      setError("PARITY ERROR: TOKEN SEQUENCE REJECTED");
      setOtp('');
      return;
    }
    setLoading(true);
    setTimeout(() => {
      const registry = JSON.parse(localStorage.getItem('SUREPATH_REGISTRY') || '[]');
      const newUser = { 
        ...formData, 
        nodeId: `SP-${Math.floor(1000 + Math.random()*8999)}`, 
        memberSince: new Date().toLocaleDateString(), 
        trustScore: 92, 
        verified: true 
      };
