interface OnboardingFlowProps {
  onComplete: () => void;
  lang: 'ID' | 'EN';
}

const OnboardingFlow: React.FC<OnboardingFlowProps> = ({ onComplete, lang }) => {
  const [currentStep, setCurrentStep] = useState(0);
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => setIsVisible(true), 500);
    return () => clearTimeout(timer);
  }, []);

  const steps = [
    {
      title: lang === 'ID' ? "Selamat Datang di Aliansi Neural" : "Welcome to the Neural Alliance",
      desc: lang === 'ID' 
        ? "SurePath bukan sekadar asuransi. Kami adalah sistem saraf digital yang melindungi aset Anda secara otonom." 
        : "SurePath is not just insurance. We are a digital nervous system that protects your assets autonomously.",
      icon: SurePathLogoIcon,
      tech: "0xSP_KERNEL_INIT",
      color: "text-primary-500"
    },
    {
      title: lang === 'ID' ? "Sinkronisasi Prediktif" : "Predictive Synchronization",
      desc: lang === 'ID' 
        ? "Node kami memantau risiko 24/7. Dari penundaan penerbangan hingga anomali kendaraan, kami bertindak sebelum Anda meminta." 
        : "Our nodes monitor risks 24/7. From flight delays to vehicle anomalies, we act before you even ask.",
      icon: Radio,
      tech: "NODE_STABILITY_MONITOR",
      color: "text-blue-400"
    },
    {
      title: lang === 'ID' ? "Klaim Visi 60 Detik" : "60-Second Vision Claim",
      desc: lang === 'ID' 
        ? "Lupakan formulir manual. AI Visi Komputer kami mengaudit kerusakan secara instan melalui kamera ponsel Anda." 
        : "Forget manual forms. Our Computer Vision AI audits damage instantly through your smartphone camera.",
      icon: Scan,
      tech: "VISION_TRANSFORMER_V5",
      color: "text-rose-400"
    },
    {
      title: lang === 'ID' ? "Aktivasi Node Anda" : "Activate Your Node",
      desc: lang === 'ID' 
        ? "Siap untuk melangkah? Masuk ke portal untuk mengaktifkan proteksi neural pertama Anda sekarang." 
        : "Ready to proceed? Enter the portal to activate your first neural protection node now.",
      icon: Zap,
      tech: "LEDGER_SYNC_READY",
      color: "text-amber-400"
    }
  ];

  const handleNext = () => {
    if (currentStep < steps.length - 1) {
      setCurrentStep(s => s + 1);
    } else {
      finish();
    }
  };

  const finish = () => {
    setIsVisible(false);
    setTimeout(() => {
      localStorage.setItem('SUREPATH_ONBOARDING_COMPLETED', 'true');
      onComplete();
    }, 500);
  };

  return (
    <div className={`fixed inset-0 z-[3000] flex items-center justify-center p-6 bg-black/60 backdrop-blur-md transition-opacity duration-700 ${isVisible ? 'opacity-100' : 'opacity-0'}`}>
