              <div className="flex items-center gap-3">
                 <div className="w-2 h-2 rounded-full bg-primary-500 animate-ping"></div>
                 <span className="text-[0.6rem] font-black text-gray-400 uppercase tracking-[0.4em]">Neural Onboarding Flow</span>
