        </div>
      </div>

      <div className="space-y-5">
        <label className="text-[0.65rem] font-black uppercase text-gray-500 ml-2 tracking-[0.3em]">Usage & Conditions Matrix</label>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
