          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
             {[0, 10000000, 25000000, 50000000].map(val => (
                <button 
                   key={val}
                   onClick={() => setCoverage({...coverage, tpl: val})}
                   className={`p-4 rounded-[1.5rem] border-2 transition-all flex flex-col items-center gap-1 tap-feedback ${coverage.tpl === val ? 'border-primary-500 bg-primary-500/5 text-primary-500 shadow-lg' : 'border-black/5 bg-white dark:bg-white/[0.03] text-gray-400 opacity-70'}`}
                >
                   <span className="font-black text-[0.7rem]">{val === 0 ? 'NONE' : `${val/1000000}JT`}</span>
                   <span className="text-[0.45rem] font-bold opacity-60">+{formatIDR(val/100)}</span>
                </button>
             ))}
          </div>
          <p className="text-[0.55rem] font-bold text-gray-400 ml-2 italic flex items-center gap-1.5"><Info size={10} className="text-primary-500"/> Premi TPL terhitung linear per kelipatan limit 10jt.</p>
       </div>

       <div className="grid grid-cols-2 gap-4">
          {[
            { id: 'authorized', label: 'Bengkel Resmi', icon: Building, desc: '+0.2% Net Premium' },
            { id: 'flood', label: 'Banjir & Badai', icon: CloudRain, desc: '+0.05% Net Premium' },
            { id: 'earthquake', label: 'Gempa & Tsunami', icon: Zap, desc: '+0.10% Net Premium' },
            { id: 'srcc', label: 'Social SRCC', icon: AlertCircle, desc: 'Variable Neural Rate' },
          ].map(opt => (
            <button 
