           return (
             <div 
               key={p.id} 
               onClick={() => setSelectedProviderId(p.id)}
               className={`p-6 rounded-[2.8rem] border-2 cursor-pointer transition-all relative overflow-hidden group tap-feedback bg-white dark:bg-white/[0.03] ${isSelected ? 'border-primary-500 shadow-2xl animate-selected-provider ring-2 ring-primary-500/20' : 'border-black/5 hover:border-black/10'}`}
             >
