      ];

      return (
        <div className="space-y-8 animate-fade-in py-4 pb-20">
          <div className="text-center space-y-4">
            <div className={`w-24 h-24 rounded-[2.5rem] mx-auto flex items-center justify-center text-white shadow-2xl transition-all duration-1000 ${survey.verdict === 'REJECTED' ? 'bg-rose-500 shadow-rose-500/40 rotate-12' : 'bg-emerald-500 shadow-emerald-500/40 animate-pop-in'}`}>
              {survey.verdict === 'REJECTED' ? <ShieldX size={48} strokeWidth={3}/> : <CheckCircle2 size={48} strokeWidth={3} />}
            </div>
            <div className="space-y-1">
               <h3 className="text-3xl font-black uppercase tracking-tighter">
                 {survey.verdict === 'REJECTED' ? 'Audit Status: Rejected' : 'Matrix Policy Ready'}
               </h3>
               <p className="text-[0.6rem] font-bold text-gray-500 uppercase tracking-widest">{survey.verdict === 'REJECTED' ? 'Registry Node terminated due to risk mismatch.' : 'Neural verification successful. Ready for deployment.'}</p>
            </div>
          </div>

          <div className="p-10 bg-white dark:bg-white/5 border-2 border-black/5 dark:border-white/5 rounded-[4rem] shadow-[0_40px_80px_-20px_rgba(0,0,0,0.1)] space-y-8 relative overflow-hidden">
             <div className="absolute top-0 right-0 p-10 opacity-5 pointer-events-none rotate-12"><Smartphone size={240}/></div>
             <div className="grid grid-cols-2 gap-y-10 gap-x-6 relative z-10">
