                    <div key={idx} className="space-y-2">
                        <div className="flex items-center gap-3 text-gray-400">
                           <item.icon size={14}/>
                           <span className="text-[0.55rem] font-black uppercase tracking-[0.2em]">{item.label}</span>
                        </div>
                        <p className={`text-[0.95rem] font-black uppercase tracking-tight truncate ${item.color || 'text-gray-900 dark:text-white'}`}>{item.value}</p>
