             <div className="pt-8 border-t border-black/5 dark:border-white/5 flex justify-between items-center relative z-10">
                <div>
                    <p className="text-[0.6rem] font-black uppercase text-gray-400 tracking-widest leading-none mb-1">Final Premium Hub</p>
                    <p className="text-3xl font-black text-primary-500 tracking-tighter leading-none">{premiumBreakdown ? formatIDR(premiumBreakdown.totalPayable) : 'Rp 0'}</p>
                </div>
                <div className="p-5 bg-gray-50 dark:bg-black/40 rounded-[2rem] border border-black/5 shadow-inner">
                   <Shield size={28} className="text-primary-500"/>
