              >
                <Wallet size={28} className="text-primary-500 group-hover:rotate-12 transition-transform"/> {survey.manualVerif ? 'SUBMITTED FOR REVIEW' : 'KONFIRMASI PEMBAYARAN'}
              </button>
            </div>
          ) : (
            <button onClick={() => setStep(0)} className="w-full py-6 bg-rose-500 text-white rounded-[2rem] font-black uppercase text-sm tracking-widest flex items-center justify-center gap-3 active:scale-95 transition-all">
               <RefreshCw size={20}/> RE-INITIALIZE REGISTRY
            </button>
          )}
        </div>
      );
  };

  return (
    <div className="flex flex-col h-full min-h-screen bg-[#f0faf7] dark:bg-dark-bg text-gray-900 dark:text-white overflow-hidden relative selection:bg-primary-100">
