export const analyzeVehicleSurvey = async (images: {id: string, data: string}[]): Promise<SurveyAnalysisResult> => {
  try {
    const ai = getAi();
    const imageParts = images.map(img => {
      const data = img.data.includes(',') ? img.data.split(',')[1] : img.data;
      return { inlineData: { mimeType: 'image/jpeg', data } };
    });

    const prompt = `Lakukan audit pra-asuransi (pre-inspection) tingkat lanjut menggunakan Computer Vision tingkat tinggi (Pro Model).
    Instruksi Kerja (Gunakan Bahasa Indonesia untuk narasi):
    1. Identifikasi Unit: Pastikan plat nomor, warna, dan merk unit konsisten di semua foto.
    2. Deteksi Fraud: Cari indikasi manipulasi digital, filter moire (foto dari layar), atau inkonsistensi metadata visual.
    3. Analisa Kondisi: Cari goresan, penyok, kaca retak, panel tidak rata, atau modifikasi yang tidak standar.
    4. Kualitas Visual: Evaluasi apakah foto cukup terang dan fokus untuk underwriting manual jika diperlukan.

    Standar Penilaian (Scoring 0-100):
    - Skor Dasar: 100.
    - Poin Pengurang:
        * Goresan Minor: -5 s/d -10 per panel.
        * Penyok/Dents: -15 s/d -20 per panel.
        * Kerusakan Berat (Lampu Pecah/Kaca Retak): -30 s/d REJECTED.
        * Indikasi Fraud: REJECTED otomatis (Skor < 50).
        * Kualitas Foto Buruk: -10 per foto.

    Audit Underwriting Guidelines Check (Return as status: PASSED, FAILED, WARNING):
    - 'Unit Integrity': Konsistensi unit di seluruh frame.
    - 'Anti-Fraud Shield': Hasil pengecekan keaslian foto digital.
    - 'Surface Health': Analisa kebersihan panel bodi.
    - 'Visual Documentation': Kelengkapan dan kejernihan dataset foto.

    Logika Putusan (Audit Verdict):
    - 'REJECTED': Skor < 60 ATAU Indikasi Fraud Terkonfirmasi.
    - 'REVIEW_REQUIRED': Skor 60-84 ATAU Ada anomali yang perlu ditinjau admin.
    - 'CLEAN': Skor >= 85 DAN Tidak ada indikasi kecurangan.

    JSON Output:
    {
      "score": number,
      "summary": "Analisis eksekutif mendalam mengenai kondisi unit (Gunakan bahasa teknis asuransi)",
      "detailedIssues": [
        { "description": "Deskripsi masalah spesifik", "severity": "Minor" | "Moderate" | "Severe", "scorePenalty": number }
      ],
      "underwritingChecks": [
        { "label": "Kriteria Audit", "status": "PASSED" | "FAILED" | "WARNING", "details": "Penjelasan teknis singkat" }
      ],
      "photoFlags": [
        { "id": "id_foto", "status": "OK" | "FRAUD_DETECTED" | "POOR_QUALITY" | "NOT_MATCHING" | "DARK_PHOTO", "reason": "Alasan detail" }
      ],
      "auditVerdict": "CLEAN" | "REVIEW_REQUIRED" | "REJECTED",
      "rejectionReason": "Penjelasan jika ditolak"
    }`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: { parts: [{ text: prompt }, ...imageParts] },
      config: { responseMimeType: 'application/json', temperature: 0.1 }
    });

    const data = JSON.parse(response.text);

    // Normalize Photo Flags
    const flagsWithIds = data.photoFlags?.map((flag: any, index: number) => ({
      ...flag,
      id: images[index]?.id || flag.id || `img_${index}`
    }));

    return { success: true, ...data, photoFlags: flagsWithIds };
  } catch (e) { 
    console.error("Vehicle Survey AI Error:", e);
    return { success: false, error: "Neural Audit Engine timeout. Please recalibrate and retry." }; 
  }
};

export const extractKtpData = async (base64: string): Promise<{ success: boolean; data?: any }> => {
  try {
    const ai = getAi();
    const cleanBase64 = base64.includes(',') ? base64.split(',')[1] : base64;
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { 
        parts: [
          { text: "Analyze this Indonesian KTP. Extract: Full Name (Nama), NIK (exactly 16 digits), and Full Address (Alamat). Return a JSON object with keys 'name', 'nik', and 'address'. Ensure NIK is cleaned of any non-numeric characters. Use uppercase for name and address. If a field is missing, use null." }, 
          { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } }
        ] 
      },
      config: { 
        responseMimeType: 'application/json',
        temperature: 0.1
      }
    });
    return { success: true, data: JSON.parse(response.text) };
  } catch (e) { 
    console.error("KTP AI Error:", e);
    return { success: false }; 
  }
};

