const CarInsuranceWizard = ({ onComplete, currentUser }: { onComplete: () => void, currentUser?: any }) => {
  const [step, setStep] = useState(0);
  const [loading, setLoading] = useState(false);
  const [loadingType, setLoadingType] = useState<'KTP' | 'STNK' | 'SURVEY' | null>(null);
  const [entryMode, setEntryMode] = useState<'DATABASE' | 'MANUAL'>('DATABASE');
  const [showBreakdown, setShowBreakdown] = useState(false);
  const [showProviderBreakdown, setShowProviderBreakdown] = useState(false);
  const [sortBy, setSortBy] = useState<'RATING' | 'PRICE'>('RATING');
  const [hasProKey, setHasProKey] = useState(false);

  const [vehicle, setVehicle] = useState({
    brand: '', model: '', year: 2025, isOther: false, 
    price: 0, basePrice: 0, manualPrice: false, plate: '', 
    region: '3' as '1'|'2'|'3', regionName: 'Region Lainnya', usage: 'PRIVATE', condition: 'NEW'
  });

  const [coverage, setCoverage] = useState({
    type: InsuranceType.COMPREHENSIVE as InsuranceType,
    flood: false, earthquake: false, srcc: false, 
    terrorism: false, authorized: false, 
    tpl: 0, paDriver: false, paPassenger: false,
    promo: '', discount: 0, discountType: 'NOMINAL' as 'NOMINAL' | 'PERCENT'
  });

  const [selectedProviderId, setSelectedProviderId] = useState<string | null>(null);
  const [kycData, setKycData] = useState({ 
    name: currentUser?.name || '', 
    ktp: currentUser?.ktp || '', 
    address: currentUser?.address || '', 
    email: currentUser?.email || '', 
    phone: currentUser?.phone || '', 
    photo: null as string|null 
  });
  const [verifiedFields, setVerifiedFields] = useState<Set<string>>(new Set());

  const [stnkResult, setStnkResult] = useState({
    ownerName: '',
    plate: '',
    vin: '',
    engine: '',
    color: '',
    year: '',
    status: ''
  });

  const [survey, setSurvey] = useState({ 
    stnk: null as string|null, 
    photos: {} as Record<string, string>, 
    score: 0, 
    summary: '',
    detailedIssues: [] as DamageIssue[], 
    underwritingChecks: [] as UnderwritingCheck[],
    photoFlags: [] as PhotoFlag[],
    verdict: '' as 'CLEAN' | 'REVIEW_REQUIRED' | 'REJECTED' | '',
    rejectionReason: '',
    manualVerif: false, 
    accessories: '' 
  });

  useEffect(() => {
    const checkKey = async () => {
       const selected = await window.aistudio.hasSelectedApiKey();
       setHasProKey(selected);
    };
    checkKey();
  }, []);

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const data = JSON.parse(saved);
        if (data.step !== undefined) setStep(data.step);
        if (data.vehicle) setVehicle(data.vehicle);
        if (data.coverage) setCoverage(data.coverage);
        if (data.selectedProviderId) setSelectedProviderId(data.selectedProviderId);
        if (data.kycData) setKycData(data.kycData);
        if (data.survey) setSurvey(data.survey);
        if (data.stnkResult) setStnkResult(data.stnkResult);
      } catch (err) {
        console.error("Failed to restore wizard progress", err);
      }
    }
  }, []);

  useEffect(() => {
    const timer = setTimeout(() => {
      const stateToSave = {
        step,
        vehicle,
        coverage,
        selectedProviderId,
        kycData,
        survey,
        stnkResult
      };
      try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(stateToSave));
      } catch (err) {
        console.warn("Storage quota exceeded");
      }
    }, 1000); 
    return () => clearTimeout(timer);
  }, [step, vehicle, coverage, selectedProviderId, kycData, survey, stnkResult]);

  const clearProgress = () => {
    localStorage.removeItem(STORAGE_KEY);
  };

  useEffect(() => {
    if (vehicle.condition === 'NEW') {
        setVehicle(prev => ({ ...prev, year: 2025 }));
    }
  }, [vehicle.condition]);

  const selectedProvider = useMemo(() => INSURANCE_PROVIDERS.find(p => p.id === selectedProviderId), [selectedProviderId]);

  const premiumBreakdown = useMemo(() => {
    if (!vehicle.price) return null;
    const baseRate = getOJKRate(vehicle.price / 1000000, vehicle.region, coverage.type);
    const basicPremium = (vehicle.price * baseRate) / 100;

    const expansions = [];
    if (coverage.authorized) expansions.push({ name: 'Bengkel Resmi (Authorized)', val: (vehicle.price * AUTHORIZED_WORKSHOP_RATE) / 100, rate: AUTHORIZED_WORKSHOP_RATE });
    if (coverage.flood) expansions.push({ name: 'Banjir & Angin Ribut', val: (vehicle.price * EXPANSION_RATES.FLOOD) / 100, rate: EXPANSION_RATES.FLOOD });
    if (coverage.earthquake) expansions.push({ name: 'Gempa & Tsunami', val: (vehicle.price * EXPANSION_RATES.EARTHQUAKE) / 100, rate: EXPANSION_RATES.EARTHQUAKE });

    const srccRate = coverage.type === InsuranceType.COMPREHENSIVE ? EXPANSION_RATES.SRCC.COMPREHENSIVE : EXPANSION_RATES.SRCC.TLO;
    if (coverage.srcc) expansions.push({ name: 'SRCC (Kerusuhan)', val: (vehicle.price * srccRate) / 100, rate: srccRate });

    const tsRate = coverage.type === InsuranceType.COMPREHENSIVE ? EXPANSION_RATES.TERRORISM.COMPREHENSIVE : EXPANSION_RATES.TERRORISM.TLO;
    if (coverage.terrorism) expansions.push({ name: 'Terorisme & Sabotase', val: (vehicle.price * tsRate) / 100, rate: tsRate });

    const tplPremium = (coverage.tpl / 100); 
    const expansionTotal = expansions.reduce((acc: number, curr: any) => acc + curr.val, 0) + tplPremium;
    const netPremium = basicPremium + expansionTotal;

    return {
        baseRate, basicPremium, expansions, tplPremium,
        adminFee: selectedProvider?.adminFee || 0,
        stampDuty: STAMP_DUTY,
        netPremium,
        totalPayable: netPremium + (selectedProvider?.adminFee || 0) + STAMP_DUTY
    };
  }, [vehicle, coverage, selectedProvider]);

  const sortedProviders = useMemo(() => {
    return [...INSURANCE_PROVIDERS].sort((a, b) => {
      if (sortBy === 'RATING') return b.rating - a.rating;
      if (sortBy === 'PRICE') {
          const priceA = (premiumBreakdown?.netPremium || 0) + a.adminFee;
          const priceB = (premiumBreakdown?.netPremium || 0) + b.adminFee;
          return priceA - priceB;
      }
      return 0;
    });
  }, [sortBy, premiumBreakdown]);

  const handleNext = () => setStep(s => Math.min(s + 1, STEPS.length - 1));
  const handleBack = () => setStep(s => Math.max(s - 1, 0));

  const formatInputCurrency = (value: string) => {
    const numeric = value.replace(/\D/g, "");
    if (!numeric) return "";
    return new Intl.NumberFormat('id-ID').format(parseInt(numeric));
  };

  const handlePlateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let val = e.target.value.toUpperCase();
    val = val.replace(/[^A-Z0-9]/g, "");
    const parts = val.match(/^([A-Z]{1,2})([0-9]{0,4})([A-Z]{0,3})$/);
    if (parts) {
      const plate = `${parts[1]}${parts[2] ? ' ' + parts[2] : ''}${parts[3] ? ' ' + parts[3] : ''}`;
      const prefix = parts[1];
      const regionInfo = PLATE_REGIONS[prefix];
      setVehicle({
        ...vehicle, 
        plate, 
        region: regionInfo?.region || '3', 
        regionName: regionInfo ? `${regionInfo.name} (Region ${regionInfo.region})` : 'Region 3 (Lainnya)'
      });
    } else {
      setVehicle({...vehicle, plate: val});
    }
  };

  const handleStnkUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setLoading(true);
    setLoadingType('STNK');
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      setSurvey(prev => ({ ...prev, stnk: base64 }));
      const response = await extractStnkData(base64);
      setLoading(false);
      setLoadingType(null);
      if (response.success && response.data) {
        setStnkResult({
          ownerName: response.data.owner || 'TIDAK TERDETEKSI',
          plate: response.data.plate || 'TIDAK TERDETEKSI',
          vin: response.data.vin || 'TIDAK TERDETEKSI',
          engine: response.data.engine || 'TIDAK TERDETEKSI',
          color: response.data.color || 'TIDAK TERDETEKSI',
          year: response.data.year || vehicle.year.toString(),
          status: response.data.status
        });
      }
    };
    reader.readAsDataURL(file);
  };

  const runSurveyAI = async () => {
    const photoEntries = Object.entries(survey.photos).map(([id, data]) => ({ id, data: data as string }));
    if (photoEntries.length < 5) {
      alert("Harap lengkapi semua foto unit (5 posisi) sebelum memulai audit AI.");
      return;
    }
    setLoading(true);
    setLoadingType('SURVEY');

    const response = await analyzeVehicleSurvey(photoEntries);

    setLoading(false);
    setLoadingType(null);

    if (response.success) {
      const finalScore = response.score || 0;

      const needsManualApproval = finalScore < 60 || response.auditVerdict === 'REVIEW_REQUIRED';
      const isRejected = response.auditVerdict === 'REJECTED';

      setSurvey(prev => ({ 
        ...prev, 
        score: finalScore, 
        summary: response.summary || '',
        detailedIssues: response.detailedIssues || [],
        underwritingChecks: response.underwritingChecks || [],
        photoFlags: response.photoFlags || [],
        verdict: isRejected ? 'REJECTED' : (needsManualApproval ? 'REVIEW_REQUIRED' : 'CLEAN'),
        rejectionReason: response.rejectionReason || (finalScore < 50 ? 'Skor audit neural di bawah batas kritis.' : ''),
        manualVerif: needsManualApproval && !isRejected
      }));
    } else {
       if (response.error?.includes("NEURAL_AUTH_REQUIRED")) {
          alert("Neural Underwriting Pro requires an API key. Please select your key in the Pro Model Hub.");
          await window.aistudio.openSelectKey();
          setHasProKey(true);
       } else {
          alert(response.error || "Audit failed. Please retry.");
       }
    }
  };

  const renderStepVehicle = () => (
    <div className="space-y-6 animate-fade-in">
      <div className="flex bg-gray-100 dark:bg-white/[0.03] p-1 rounded-[1.8rem] border border-black/5 dark:border-white/5">
         <button 
           onClick={() => setEntryMode('DATABASE')}
           className={`flex-1 py-3.5 rounded-[1.5rem] text-[0.65rem] font-black uppercase tracking-widest transition-all flex items-center justify-center gap-2 ${entryMode === 'DATABASE' ? 'bg-white dark:bg-gray-800 shadow-xl text-primary-500' : 'text-gray-400'}`}
         >
           <Database size={16}/> Neural Database
         </button>
         <button 
           onClick={() => { setEntryMode('MANUAL'); setVehicle(v => ({ ...v, brand: '', model: '', basePrice: 0 })); }}
           className={`flex-1 py-3.5 rounded-[1.5rem] text-[0.65rem] font-black uppercase tracking-widest transition-all flex items-center justify-center gap-2 ${entryMode === 'MANUAL' ? 'bg-white dark:bg-gray-800 shadow-xl text-primary-500' : 'text-gray-400'}`}
         >
           <Edit3 size={16}/> Manual Registry
         </button>
      </div>

      <div className="space-y-5">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
          <div className="space-y-2">
            <label className="text-[0.6rem] font-black uppercase text-gray-500 ml-2 tracking-[0.2em]">Merk Kendaraan</label>
            {entryMode === 'DATABASE' ? (
                <div className="relative group">
                    <select 
                        className="w-full p-5 rounded-[1.8rem] bg-white dark:bg-white/[0.03] border-2 border-black/5 dark:border-white/5 outline-none focus:border-primary-500 font-black text-sm appearance-none transition-all cursor-pointer group-hover:border-black/10 text-primary-500"
                        value={vehicle.brand}
                        onChange={(e) => {
                            const val = e.target.value;
                            const unit = CAR_DATABASE.find(c => c.brand === val);
                            const p = (unit?.yearPrices[2024] || 0) * 1000000;
                            setVehicle({...vehicle, brand: val, model: unit?.modelName || '', price: p, basePrice: p});
                        }}
                    >
                        <option value="">Pilih Merk</option>
                        {Array.from(new Set(CAR_DATABASE.map(c => c.brand))).sort().map(b => <option key={b} value={b}>{b}</option>)}
                    </select>
                    <div className="absolute right-5 top-1/2 -translate-y-1/2 pointer-events-none text-gray-400">
                        <ChevronDown size={20}/>
