                <div className="px-4 py-1.5 text-[0.65rem] font-black text-primary-600 uppercase tracking-widest">{STEPS[step].label}</div>
             </div>
             <p className="text-[0.6rem] font-black text-gray-400 uppercase tracking-[0.2em]">Step {step + 1} of {STEPS.length}</p>
          </div>

          <div className="flex gap-2.5">
             {STEPS.map((s, i) => (<div key={i} className={`h-2 rounded-full flex-1 transition-all duration-700 ${i === step ? 'bg-primary-500 shadow-[0_0_15px_#10b981]' : i < step ? 'bg-primary-500/30' : 'bg-gray-200 dark:bg-white/10'}`}></div>))}
          </div>
       </div>

       <div className="flex-1 overflow-y-auto px-8 py-10 no-scrollbar relative z-10">
          <div className="max-w-xl mx-auto">
            {step === 0 && renderStepVehicle()}
            {step === 1 && renderStepCoverage()}
            {step === 2 && renderStepProviders()}
            {step === 3 && renderStepKYC()}
            {step === 4 && renderStepPreSummary()}
            {step === 5 && renderStepSurvey()}
            {step === 6 && renderStepFinal()}
          </div>
       </div>

       <div className="px-8 py-8 bg-white dark:bg-[#111] border-t border-black/5 flex items-center justify-between gap-8 flex-shrink-0 sticky bottom-0 z-[100] shadow-[0_-20px_50px_rgba(0,0,0,0.05)]">
          <div className="flex-1">
             <p className="text-[0.7rem] font-black uppercase text-gray-500 leading-none mb-2 tracking-[0.2em]">Estimasi Premi</p>
             <p className="text-3xl font-black tracking-tighter text-primary-600 leading-none">{premiumBreakdown ? formatIDR(premiumBreakdown.totalPayable) : 'Rp 0'}</p>
          </div>
          <div className="flex gap-4">
             {step > 0 && (<button onClick={handleBack} className="p-5 bg-gray-50 dark:bg-white/5 rounded-3xl text-gray-400 hover:text-primary-500 transition-all shadow-sm border border-black/5 active:scale-95"><ChevronLeft size={28}/></button>)}
             {step < STEPS.length - 1 && (
                <button 
                  onClick={handleNext} 
                  disabled={(step === 5 && survey.score === 0)}
                  className="px-12 py-5 bg-primary-600 text-white rounded-[1.8rem] font-black uppercase text-[0.85rem] tracking-[0.2em] shadow-xl shadow-primary-500/20 transition-all active:scale-95 flex items-center gap-3 disabled:opacity-30 disabled:grayscale group"
                >
                  {step === 5 && survey.manualVerif ? 'Kirim Review' : 'Lanjutkan'} <ChevronRight size={20} className="group-hover:translate-x-1 transition-transform"/>
                </button>
             )}
          </div>
       </div>
    </div>
  );
};

