import React, { useState, useMemo } from 'react';
import { 
  Car, Shield, CreditCard, ChevronRight, ChevronLeft, 
  Upload, Check, AlertCircle, Calendar, MapPin, 
  FileText, User, Smartphone, Mail, Loader2, Camera,
  Scan, CheckCircle2, Wallet, Zap, ShieldCheck, ArrowRight
} from 'lucide-react';
import { extractKtpData, extractStnkData } from '../services/geminiService';
import { VehicleState, InsuranceType } from '../types';
import { getOJKRate, EXPANSION_RATES, PLATE_REGIONS } from '../constants';

const formatIDR = (n: number) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', minimumFractionDigits: 0 }).format(n);

const STEPS = ['Vehicle Data', 'Coverage Config', 'Identity Verification', 'Policy Activation'];

const CarInsuranceWizard = ({ onComplete, currentUser }: { onComplete: () => void, currentUser?: any }) => {
  const [step, setStep] = useState(0);
  const [loading, setLoading] = useState(false);
  const [loadingType, setLoadingType] = useState<string | null>(null);

  const [vehicle, setVehicle] = useState<Partial<VehicleState>>({
    brand: '',
    model: '',
    year: new Date().getFullYear(),
    price: 0,
    plate: '',
    region: '2',
    insuranceType: InsuranceType.COMPREHENSIVE,
    expansions: {
      flood: false,
      earthquake: false,
      srcc: false,
      terrorism: false,
      authorizedWorkshop: false,
      tpl: 0,
      paDriver: false,
      paPassenger: false
    }
  });

  const [kycData, setKycData] = useState({
    name: currentUser?.name || '',
    ktp: currentUser?.ktp || '',
    address: '',
    email: currentUser?.email || '',
    phone: currentUser?.phone || '',
    photo: null as string | null
  });

  const [verifiedFields, setVerifiedFields] = useState<Set<string>>(new Set());

  const premium = useMemo(() => {
    if (!vehicle.price || !vehicle.insuranceType || !vehicle.region) return 0;

    const priceMillions = vehicle.price / 1000000;
    const region = vehicle.region as '1'|'2'|'3';
    const rate = getOJKRate(priceMillions, region, vehicle.insuranceType);

    let basePremium = vehicle.price * (rate / 100);

    // Simple expansion logic for demo
    if (vehicle.expansions?.flood) basePremium += vehicle.price * (EXPANSION_RATES.FLOOD / 100);
    if (vehicle.expansions?.earthquake) basePremium += vehicle.price * (EXPANSION_RATES.EARTHQUAKE / 100);

    return basePremium;
  }, [vehicle]);

  const handleNext = () => setStep(s => Math.min(s + 1, STEPS.length - 1));
  const handleBack = () => setStep(s => Math.max(s - 1, 0));

  const handleStnkUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setLoading(true);
    setLoadingType('STNK');
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      const response = await extractStnkData(base64);
      setLoading(false);
      setLoadingType(null);
      if (response.success && response.data) {
        setVehicle(prev => ({
          ...prev,
          plate: response.data.plate || prev.plate,
          brand: response.data.brand || prev.brand,
          year: parseInt(response.data.year) || prev.year,
          region: response.data.plate ? (PLATE_REGIONS[response.data.plate.split(' ')[0]]?.region || '1') : prev.region
        }));
