      </div>

      <div className="relative group cursor-pointer">
        <div className={`p-8 rounded-[2.5rem] border-2 border-dashed ${loading ? 'border-primary-500 bg-primary-500/5' : 'border-gray-300 dark:border-white/10 bg-gray-50 dark:bg-white/5'} text-center transition-all hover:border-primary-500`}>
