                <p className="text-[0.7rem] font-black uppercase text-gray-900 dark:text-white tracking-widest">Scan STNK Document</p>
                <p className="text-[0.55rem] font-bold text-gray-400 uppercase tracking-widest mt-1">Auto-fill via OCR</p>
