             </div>
           ) : (
             <>
                <div className="w-16 h-16 bg-white dark:bg-white/10 rounded-2xl flex items-center justify-center mx-auto mb-4 shadow-sm group-hover:scale-110 transition-transform">
                   <User size={32} className="text-gray-400 group-hover:text-primary-500"/>
                </div>
                <p className="text-[0.7rem] font-black uppercase text-gray-900 dark:text-white tracking-widest">Upload KTP</p>
                <p className="text-[0.55rem] font-bold text-gray-400 uppercase tracking-widest mt-1">Neural KYC Check</p>
             </>
           )}
           <input 
             type="file" 
             accept="image/*"
             className="absolute inset-0 opacity-0 cursor-pointer"
             onChange={async (e) => {
               const file = e.target.files?.[0];
               if (!file) return;
               setLoading(true);
               setLoadingType('KTP');
               const reader = new FileReader();
               reader.onload = async () => {
                 const base64 = reader.result as string;
                 setKycData(prev => ({ ...prev, photo: base64 }));
                 const response = await extractKtpData(base64);
                 setLoading(false);
                 setLoadingType(null);
                 if (response.success && response.data) {
                   const newVerified = new Set<string>();
                   if (response.data.name) newVerified.add('name');
                   if (response.data.nik) newVerified.add('ktp');
                   if (response.data.address) newVerified.add('address');
                   setVerifiedFields(newVerified);
                   setKycData(prev => ({
                     ...prev,
                     name: response.data.name?.toUpperCase() || prev.name,
                     ktp: response.data.nik || prev.ktp,
                     address: response.data.address?.toUpperCase() || prev.address
                   }));
                 }
               };
               reader.readAsDataURL(file);
             }}
             disabled={loading}
           />
        </div>
      </div>

      <div className="space-y-4">
         <div className="space-y-1.5 relative">
            <label className="text-[0.5rem] font-black uppercase text-gray-400 ml-1">Full Name</label>
            <input 
               value={kycData.name}
               onChange={(e) => setKycData({...kycData, name: e.target.value.toUpperCase()})}
               className={`w-full px-5 py-4 rounded-2xl bg-white dark:bg-white/5 border-2 ${verifiedFields.has('name') ? 'border-emerald-500/50' : 'border-black/5'} outline-none focus:border-primary-500 font-black text-sm uppercase`}
