      title: lang === 'ID' ? "Visi Komputer" : "Computer Vision",
      subtitle: lang === 'ID' ? "Klaim 60 Detik" : "60s Claim",
      desc: lang === 'ID' 
        ? "Lupakan formulir manual. AI kami mengaudit kerusakan fisik secara instan melalui kamera ponsel Anda." 
        : "Forget manual forms. Our Computer Vision AI audits physical damage instantly through your smartphone camera.",
      icon: Scan,
      tech: "VISION_TRANSFORMER::V5.2",
      color: "text-rose-400",
      bgGlow: "bg-rose-500/20"
    },
    {
      title: lang === 'ID' ? "Aktivasi Node" : "Node Activation",
      subtitle: lang === 'ID' ? "Mulai Proteksi" : "Start Protection",
      desc: lang === 'ID' 
        ? "Siap untuk melangkah? Masuk ke portal untuk mengaktifkan proteksi neural pertama Anda sekarang." 
        : "Ready to proceed? Enter the portal to activate your first neural protection node now.",
      icon: Zap,
      tech: "LEDGER_SYNC::READY",
      color: "text-amber-400",
      bgGlow: "bg-amber-500/20"
    }
  ];

  const handleNext = () => {
    if (animating) return;
    setAnimating(true);

    if (currentStep < steps.length - 1) {
      setTimeout(() => {
        setCurrentStep(s => s + 1);
        setAnimating(false);
      }, 300);
    } else {
      finish();
    }
  };

  const finish = () => {
    setIsVisible(false);
    setTimeout(() => {
      localStorage.setItem('SUREPATH_ONBOARDING_COMPLETED', 'true');
      onComplete();
    }, 500);
  };

  const CurrentIcon = steps[currentStep].icon;

  return (
    <div className={`fixed inset-0 z-[3000] flex items-center justify-center p-0 md:p-6 bg-black/90 backdrop-blur-xl transition-opacity duration-700 ${isVisible ? 'opacity-100' : 'opacity-0'}`}>

      {/* Dynamic Background Elements */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none">
         <div className={`absolute top-[-20%] left-[-20%] w-[800px] h-[800px] rounded-full blur-[150px] opacity-20 transition-colors duration-1000 ${steps[currentStep].bgGlow.replace('/20', '')}`}></div>
         <div className={`absolute bottom-[-20%] right-[-20%] w-[600px] h-[600px] rounded-full blur-[150px] opacity-20 transition-colors duration-1000 ${steps[currentStep].bgGlow.replace('/20', '')}`} style={{ transitionDelay: '200ms' }}></div>
         <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')] opacity-10"></div>
      </div>

      <div className={`w-full h-full md:h-auto md:max-w-md glass-titan md:rounded-[3.5rem] border-0 md:border-2 border-white/10 shadow-[0_0_80px_rgba(0,0,0,0.8)] overflow-hidden flex flex-col relative transition-transform duration-500 ${isVisible ? 'scale-100' : 'scale-95'}`}>

        {/* Top Progress Bar (Instagram Story Style) */}
        <div className="absolute top-0 left-0 w-full p-6 md:p-8 z-20">
           <div className="flex gap-2">
              {steps.map((_, i) => (
                <div key={i} className="h-1 flex-1 bg-white/10 rounded-full overflow-hidden">
                   <div 
                     className={`h-full bg-white transition-all duration-500 ease-out ${i <= currentStep ? 'w-full' : 'w-0'} ${i === currentStep ? 'opacity-100' : 'opacity-30'}`}
                   ></div>
                </div>
              ))}
           </div>
        </div>

        {/* Content Wrapper */}
        <div className="flex-1 flex flex-col relative">

           {/* Visual Section */}
           <div className="flex-1 flex items-center justify-center relative min-h-[400px] md:min-h-[380px]">
              {/* Holographic Platform */}
              <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[300px] h-[300px]">
                 <div className={`absolute inset-0 rounded-full border border-white/5 animate-[spin_10s_linear_infinite]`}></div>
                 <div className={`absolute inset-10 rounded-full border border-white/5 animate-[spin_15s_linear_infinite_reverse]`}></div>
                 <div className={`absolute inset-0 rounded-full ${steps[currentStep].bgGlow} blur-[60px] animate-pulse`}></div>
              </div>

              {/* Floating Icon */}
              <div key={currentStep} className="relative z-10 animate-pop-in">
                 <div className={`w-32 h-32 md:w-40 md:h-40 bg-black/40 backdrop-blur-md rounded-[2.5rem] flex items-center justify-center border border-white/10 shadow-2xl ${steps[currentStep].color} animate-float`}>
                    <CurrentIcon size={isLogo(steps[currentStep]) ? 100 : 64} className={`drop-shadow-[0_0_15px_rgba(255,255,255,0.3)] ${isLogo(steps[currentStep]) ? '' : ''}`} />
                 </div>
                 {/* Floating Badges */}
                 <div className="absolute -right-8 top-0 bg-white/10 backdrop-blur-md border border-white/10 px-3 py-1.5 rounded-xl text-[0.55rem] font-black uppercase tracking-widest text-white animate-fade-in animation-delay-200 shadow-lg">
                    {steps[currentStep].tech.split('::')[0]}
                 </div>
              </div>
           </div>

           {/* Text Section */}
           <div className="px-8 pb-8 pt-0 relative z-20">
              <div key={currentStep} className={`space-y-6 transition-all duration-300 ${animating ? 'opacity-0 translate-y-4' : 'opacity-100 translate-y-0'}`}>
                 <div className="space-y-2">
                    <div className={`inline-flex items-center gap-2 px-3 py-1 rounded-full bg-white/5 border border-white/10 w-fit`}>
                       <Terminal size={10} className={steps[currentStep].color}/>
                       <span className="text-[0.5rem] font-mono text-gray-400 uppercase tracking-widest">{steps[currentStep].tech}</span>
                    </div>
                    <h2 className="text-4xl md:text-5xl font-black text-white leading-[0.9] tracking-tighter uppercase">
                       <span className="text-gray-500 block text-lg md:text-xl mb-1 tracking-widest">{steps[currentStep].subtitle}</span>
                       {steps[currentStep].title}
                    </h2>
                 </div>

                 <p className="text-sm md:text-base text-gray-400 font-medium leading-relaxed">
                    {steps[currentStep].desc}
                 </p>
              </div>
           </div>

           {/* Footer Actions */}
           <div className="p-8 pt-0 flex items-center gap-4 relative z-20">
              <button 
                onClick={finish}
                className="p-4 rounded-2xl bg-white/5 text-gray-500 hover:text-white hover:bg-white/10 transition-all border border-transparent hover:border-white/10"
              >
                 <X size={20}/>
              </button>

              <button 
                onClick={handleNext}
                className="flex-1 py-5 bg-white text-black rounded-2xl font-black uppercase text-xs md:text-sm tracking-[0.3em] flex items-center justify-center gap-3 shadow-[0_0_30px_rgba(255,255,255,0.1)] hover:scale-[1.02] active:scale-95 transition-all group overflow-hidden relative"
              >
                 <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/50 to-transparent translate-x-[-100%] group-hover:translate-x-[100%] transition-transform duration-700"></div>
                 <span className="relative z-10">{currentStep === steps.length - 1 ? (lang === 'ID' ? 'Aktivasi' : 'Initialize') : (lang === 'ID' ? 'Lanjut' : 'Next Step')}</span>
                 <ArrowRight size={18} className="relative z-10 group-hover:translate-x-1 transition-transform"/>
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

// Helper type guard
function isLogo(step: any): boolean {
  return step.isLogo === true;
}

export default OnboardingFlow;

import React, { useState, useMemo } from 'react';
import { 
  Car, Shield, CreditCard, ChevronRight, ChevronLeft, 
  Upload, Check, AlertCircle, Calendar, MapPin, 
  FileText, User, Smartphone, Mail, Loader2, Camera,
  Scan, CheckCircle2, Wallet, Zap, ShieldCheck, ArrowRight
} from 'lucide-react';
import { extractKtpData, extractStnkData } from '../services/geminiService';
import { VehicleState, InsuranceType } from '../types';
import { getOJKRate, EXPANSION_RATES, PLATE_REGIONS } from '../constants';

const formatIDR = (n: number) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', minimumFractionDigits: 0 }).format(n);

const STEPS = ['Vehicle Data', 'Coverage Config', 'Identity Verification', 'Policy Activation'];

const CarInsuranceWizard = ({ onComplete, currentUser }: { onComplete: () => void, currentUser?: any }) => {
  const [step, setStep] = useState(0);
  const [loading, setLoading] = useState(false);
  const [payLoading, setPayLoading] = useState(false);
  const [loadingType, setLoadingType] = useState<string | null>(null);

  const [vehicle, setVehicle] = useState<Partial<VehicleState>>({
    brand: '',
    model: '',
    year: new Date().getFullYear(),
    price: 0,
    plate: '',
    region: '2',
    insuranceType: InsuranceType.COMPREHENSIVE,
    expansions: {
      flood: false,
      earthquake: false,
      srcc: false,
      terrorism: false,
      authorizedWorkshop: false,
      tpl: 0,
      paDriver: false,
      paPassenger: false
    }
  });

  const [kycData, setKycData] = useState({
    name: currentUser?.name || '',
    ktp: currentUser?.ktp || '',
    address: '',
    email: currentUser?.email || '',
    phone: currentUser?.phone || '',
    photo: null as string | null
  });

  const [verifiedFields, setVerifiedFields] = useState<Set<string>>(new Set());

  const premium = useMemo(() => {
    if (!vehicle.price || !vehicle.insuranceType || !vehicle.region) return 0;

    const priceMillions = vehicle.price / 1000000;
    const region = vehicle.region as '1'|'2'|'3';
    const rate = getOJKRate(priceMillions, region, vehicle.insuranceType);

    let basePremium = vehicle.price * (rate / 100);

    // Simple expansion logic for demo
    if (vehicle.expansions?.flood) basePremium += vehicle.price * (EXPANSION_RATES.FLOOD / 100);
    if (vehicle.expansions?.earthquake) basePremium += vehicle.price * (EXPANSION_RATES.EARTHQUAKE / 100);

    return basePremium;
  }, [vehicle]);

  const handleNext = () => setStep(s => Math.min(s + 1, STEPS.length - 1));
  const handleBack = () => setStep(s => Math.max(s - 1, 0));

  const handleStnkUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setLoading(true);
    setLoadingType('STNK');
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      const response = await extractStnkData(base64);
      setLoading(false);
      setLoadingType(null);
      if (response.success && response.data) {
        setVehicle(prev => ({
          ...prev,
          plate: response.data.plate || prev.plate,
          brand: response.data.brand || prev.brand,
          year: parseInt(response.data.year) || prev.year,
          region: response.data.plate ? (PLATE_REGIONS[response.data.plate.split(' ')[0]]?.region || '1') : prev.region
        }));
      }
    };
    reader.readAsDataURL(file);
  };

  const renderStep0 = () => (
    <div className="space-y-6 animate-fade-in">
      <div className="p-4 bg-primary-500/10 rounded-3xl border border-primary-500/20 flex gap-4">
