         <p className="text-[0.65rem] font-bold text-gray-600 dark:text-gray-300 leading-relaxed uppercase tracking-wider">
           Neural Auto OS. Upload STNK for instant parameter extraction.
         </p>
      </div>

      <div className="relative group cursor-pointer">
        <div className={`p-8 rounded-[2.5rem] border-2 border-dashed ${loading ? 'border-primary-500 bg-primary-500/5' : 'border-gray-300 dark:border-white/10 bg-gray-50 dark:bg-white/5'} text-center transition-all hover:border-primary-500`}>
           {loading && loadingType === 'STNK' ? (
             <div className="flex flex-col items-center gap-3">
                <Loader2 className="animate-spin text-primary-500" size={32}/>
                <p className="text-[0.6rem] font-black uppercase tracking-widest text-primary-500 animate-pulse">Scanning Neural Pattern...</p>
             </div>
           ) : (
             <>
                <div className="w-16 h-16 bg-white dark:bg-white/10 rounded-2xl flex items-center justify-center mx-auto mb-4 shadow-sm group-hover:scale-110 transition-transform">
                   <Scan size={32} className="text-gray-400 group-hover:text-primary-500"/>
                </div>
                <p className="text-[0.7rem] font-black uppercase text-gray-900 dark:text-white tracking-widest">Scan STNK Document</p>
                <p className="text-[0.55rem] font-bold text-gray-400 uppercase tracking-widest mt-1">Auto-fill via OCR</p>
             </>
           )}
           <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleStnkUpload} disabled={loading}/>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4">
         <div className="space-y-1.5">
            <label className="text-[0.5rem] font-black uppercase text-gray-400 ml-1">Car Plate</label>
            <input 
              value={vehicle.plate}
              onChange={(e) => setVehicle({...vehicle, plate: e.target.value.toUpperCase()})}
              placeholder="B 1234 CD"
              className="w-full px-5 py-4 rounded-2xl bg-white dark:bg-white/5 border-2 border-black/5 outline-none focus:border-primary-500 font-black text-sm uppercase"
            />
