              onChange={(e) => setVehicle({...vehicle, year: parseInt(e.target.value)})}
              className="w-full px-5 py-4 rounded-2xl bg-white dark:bg-white/5 border-2 border-black/5 outline-none focus:border-primary-500 font-black text-sm"
            />
         </div>
      </div>

      <div className="space-y-1.5">
         <label className="text-[0.5rem] font-black uppercase text-gray-400 ml-1">Car Value (IDR)</label>
         <input 
            type="number"
            value={vehicle.price || ''}
            onChange={(e) => setVehicle({...vehicle, price: parseInt(e.target.value)})}
