            className="w-full px-5 py-4 rounded-2xl bg-white dark:bg-white/5 border-2 border-black/5 outline-none focus:border-primary-500 font-black text-sm"
         />
      </div>
    </div>
  );

  const renderStep1 = () => (
    <div className="space-y-6 animate-fade-in">
       <div className="flex gap-4">
          {[
            { id: InsuranceType.COMPREHENSIVE, label: 'Comprehensive', desc: 'All Risk Protection' },
            { id: InsuranceType.TLO, label: 'TLO', desc: 'Total Loss Only' }
          ].map(type => (
             <button
                key={type.id}
                onClick={() => setVehicle({...vehicle, insuranceType: type.id})}
                className={`flex-1 p-5 rounded-[2rem] border-2 text-left transition-all ${vehicle.insuranceType === type.id ? 'border-primary-500 bg-primary-500/5' : 'border-black/5 bg-white dark:bg-white/5 opacity-60'}`}
             >
                <div className={`w-8 h-8 rounded-full flex items-center justify-center mb-3 ${vehicle.insuranceType === type.id ? 'bg-primary-500 text-white' : 'bg-gray-200 dark:bg-white/20 text-gray-500'}`}>
                   {vehicle.insuranceType === type.id && <Check size={14} strokeWidth={3}/>}
                </div>
                <p className="text-[0.6rem] font-black uppercase tracking-widest">{type.label}</p>
                <p className="text-[0.5rem] font-bold text-gray-400 uppercase tracking-widest mt-1">{type.desc}</p>
             </button>
          ))}
       </div>

       <div className="space-y-3">
          <p className="text-[0.55rem] font-black uppercase text-gray-400 tracking-[0.2em] ml-2">Neural Add-ons</p>
          {[
            { id: 'flood', label: 'Flood & Storm' },
            { id: 'earthquake', label: 'Earthquake' },
            { id: 'srcc', label: 'Riot & Strike' }
          ].map(opt => (
             <div 
               key={opt.id}
               onClick={() => setVehicle({
                 ...vehicle, 
                 expansions: { ...vehicle.expansions, [opt.id]: !vehicle.expansions?.[opt.id as keyof typeof vehicle.expansions] } as any
               })}
               className={`p-4 rounded-2xl border-2 flex items-center justify-between cursor-pointer transition-all ${vehicle.expansions?.[opt.id as keyof typeof vehicle.expansions] ? 'border-primary-500 bg-primary-500/5' : 'border-black/5 bg-white dark:bg-white/5'}`}
             >
                <span className="text-[0.6rem] font-black uppercase tracking-widest">{opt.label}</span>
                <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center transition-all ${vehicle.expansions?.[opt.id as keyof typeof vehicle.expansions] ? 'border-primary-500 bg-primary-500 text-white' : 'border-gray-300'}`}>
                   {vehicle.expansions?.[opt.id as keyof typeof vehicle.expansions] && <Check size={10} strokeWidth={4}/>}
                </div>
             </div>
          ))}
       </div>
    </div>
  );

  const renderStep2 = () => (
    <div className="space-y-6 animate-fade-in">
       <div className="relative group cursor-pointer">
        <div className={`p-8 rounded-[2.5rem] border-2 border-dashed ${loading && loadingType === 'KTP' ? 'border-primary-500 bg-primary-500/5' : 'border-gray-300 dark:border-white/10 bg-gray-50 dark:bg-white/5'} text-center transition-all hover:border-primary-500`}>
           {loading && loadingType === 'KTP' ? (
             <div className="flex flex-col items-center gap-3">
                <Loader2 className="animate-spin text-primary-500" size={32}/>
                <p className="text-[0.6rem] font-black uppercase tracking-widest text-primary-500 animate-pulse">Extracting Identity...</p>
             </div>
           ) : (
             <>
                <div className="w-16 h-16 bg-white dark:bg-white/10 rounded-2xl flex items-center justify-center mx-auto mb-4 shadow-sm group-hover:scale-110 transition-transform">
                   <User size={32} className="text-gray-400 group-hover:text-primary-500"/>
                </div>
                <p className="text-[0.7rem] font-black uppercase text-gray-900 dark:text-white tracking-widest">Upload KTP</p>
                <p className="text-[0.55rem] font-bold text-gray-400 uppercase tracking-widest mt-1">Neural KYC Check</p>
             </>
           )}
           <input 
             type="file" 
             accept="image/*"
             className="absolute inset-0 opacity-0 cursor-pointer"
             onChange={async (e) => {
               const file = e.target.files?.[0];
               if (!file) return;
               setLoading(true);
               setLoadingType('KTP');
               const reader = new FileReader();
               reader.onload = async () => {
                 const base64 = reader.result as string;
                 setKycData(prev => ({ ...prev, photo: base64 }));
                 const response = await extractKtpData(base64);
                 setLoading(false);
                 setLoadingType(null);
                 if (response.success && response.data) {
                   const newVerified = new Set<string>();
                   if (response.data.name) newVerified.add('name');
                   if (response.data.nik) newVerified.add('ktp');
                   if (response.data.address) newVerified.add('address');
                   setVerifiedFields(newVerified);
                   setKycData(prev => ({
                     ...prev,
                     name: response.data.name?.toUpperCase() || prev.name,
                     ktp: response.data.nik || prev.ktp,
                     address: response.data.address?.toUpperCase() || prev.address
                   }));
                 }
               };
               reader.readAsDataURL(file);
             }}
             disabled={loading}
           />
        </div>
      </div>

      <div className="space-y-4">
         <div className="space-y-1.5 relative">
            <label className="text-[0.5rem] font-black uppercase text-gray-400 ml-1">Full Name</label>
            <input 
               value={kycData.name}
               onChange={(e) => setKycData({...kycData, name: e.target.value.toUpperCase()})}
               className={`w-full px-5 py-4 rounded-2xl bg-white dark:bg-white/5 border-2 ${verifiedFields.has('name') ? 'border-emerald-500/50' : 'border-black/5'} outline-none focus:border-primary-500 font-black text-sm uppercase`}
            />
            {verifiedFields.has('name') && <CheckCircle2 size={16} className="absolute right-4 top-9 text-emerald-500"/>}
         </div>
         <div className="space-y-1.5 relative">
            <label className="text-[0.5rem] font-black uppercase text-gray-400 ml-1">NIK Number</label>
            <input 
               value={kycData.ktp}
               onChange={(e) => setKycData({...kycData, ktp: e.target.value})}
               className={`w-full px-5 py-4 rounded-2xl bg-white dark:bg-white/5 border-2 ${verifiedFields.has('ktp') ? 'border-emerald-500/50' : 'border-black/5'} outline-none focus:border-primary-500 font-black text-sm uppercase`}
            />
            {verifiedFields.has('ktp') && <CheckCircle2 size={16} className="absolute right-4 top-9 text-emerald-500"/>}
         </div>
      </div>
    </div>
