             </div>
             <div className="flex justify-between items-center text-[0.75rem]">
                <span className="text-gray-400 font-black uppercase tracking-widest flex items-center gap-3 opacity-80"><Shield size={16} className="text-primary-500"/> Type</span>
                <span className="font-black text-right uppercase">{vehicle.insuranceType}</span>
             </div>
             <div className="flex justify-between items-center text-[0.75rem]">
                <span className="text-gray-400 font-black uppercase tracking-widest flex items-center gap-3 opacity-80"><Zap size={16} className="text-primary-500"/> Value</span>
                <span className="font-black text-right text-primary-500 tracking-widest">{formatIDR(vehicle.price || 0)}</span>
             </div>
          </div>

          <div className="pt-8 border-t border-black/5 dark:border-white/5 relative z-10">
              <div className="flex justify-between items-end">
                 <div>
                    <p className="text-[0.5rem] font-black uppercase text-gray-400 tracking-widest">Total Premi Net</p>
                    <h3 className="text-4xl font-black tracking-tighter text-primary-500">{formatIDR(premium)}</h3>
                 </div>
                 <div className="flex flex-col items-end gap-1">
                    <p className="text-[0.45rem] font-black text-emerald-500 uppercase tracking-widest flex items-center gap-1"><Check size={10}/> All Risk</p>
                    <p className="text-[0.45rem] font-black text-emerald-500 uppercase tracking-widest flex items-center gap-1"><Check size={10}/> Instant</p>
                 </div>
              </div>
          </div>
       </div>

       <button 
         onClick={() => {
            setPayLoading(true);
            setTimeout(() => {
                setPayLoading(false);
                onComplete();
            }, 1500);
         }}
         disabled={payLoading}
         className="w-full py-6 bg-gray-900 dark:bg-white text-white dark:text-black rounded-[2rem] font-black uppercase text-base tracking-[0.25em] shadow-2xl flex items-center justify-center gap-4 transition-all hover:scale-[1.02] active:scale-95 disabled:opacity-70 disabled:cursor-not-allowed"
       >
         {payLoading ? <Loader2 className="animate-spin text-primary-500" size={24}/> : <Wallet size={24} className="text-primary-500"/>}
         {payLoading ? 'PROCESSING...' : 'PAY & ACTIVATE'}
       </button>
    </div>
