// --- TYPES ---

export interface StoredPolicy {
  id: string;
  type: 'AUTO' | 'TRAVEL' | 'PA' | 'PROPERTY';
  holderName: string;
  holderId: string; // Email or NIK
  premium: number;
  date: string;
  status: 'ACTIVE' | 'PENDING' | 'EXPIRED';
  details: string; // Summary text (e.g., "Toyota Avanza B 1234")
}

export interface StoredUser {
  id: string;
  name: string;
  email: string;
  role: UserRole;
  nodeId: string;
  joinDate: string;
  status: 'VERIFIED' | 'PENDING';
}

export interface StoredClaim {
  id: string;
  policyId: string;
  holderName: string;
  type: string;
  amount: number;
  date: string;
  status: 'PENDING' | 'APPROVED' | 'PAID' | 'REJECTED';
  riskScore: number;
}

// --- KEYS ---
const KEY_POLICIES = 'SUREPATH_DB_POLICIES';
const KEY_USERS = 'SUREPATH_REGISTRY'; // Using existing key from AuthGate
const KEY_CLAIMS = 'SUREPATH_DB_CLAIMS';

// --- METHODS ---

// 1. POLICIES
export const getPolicies = (): StoredPolicy[] => {
  const data = localStorage.getItem(KEY_POLICIES);
  return data ? JSON.parse(data) : [];
};

export const savePolicy = (policy: Omit<StoredPolicy, 'id' | 'date' | 'status'>) => {
  const policies = getPolicies();
  const newPolicy: StoredPolicy = {
    ...policy,
    id: `POL-${Date.now().toString().slice(-6)}`,
    date: new Date().toISOString(),
    status: 'ACTIVE'
  };
  policies.unshift(newPolicy); // Add to top
  localStorage.setItem(KEY_POLICIES, JSON.stringify(policies));
  return newPolicy;
};

// 2. USERS
export const getUsers = (): StoredUser[] => {
  const data = localStorage.getItem(KEY_USERS);
  const users = data ? JSON.parse(data) : [];
  // Ensure we return typed users, filtering out legacy data if needed
  return users.map((u: any) => ({
    id: u.email || u.nodeId,
    name: u.name,
    email: u.email,
    role: u.role || UserRole.CUSTOMER,
    nodeId: u.nodeId || 'N/A',
    joinDate: u.memberSince || new Date().toISOString(),
    status: u.verified ? 'VERIFIED' : 'PENDING'
  }));
};

export const saveUser = (user: any) => {
  const users = getUsers();
  // Check duplicate
  if (!users.find(u => u.email === user.email)) {
    users.push(user);
    localStorage.setItem(KEY_USERS, JSON.stringify(users));
  }
};

// 3. CLAIMS
export const getClaims = (): StoredClaim[] => {
  const data = localStorage.getItem(KEY_CLAIMS);
  return data ? JSON.parse(data) : [];
};

export const saveClaim = (claim: Omit<StoredClaim, 'id' | 'date' | 'status'>) => {
  const claims = getClaims();
  const newClaim: StoredClaim = {
    ...claim,
    id: `CLM-${Date.now().toString().slice(-6)}`,
    date: new Date().toISOString(),
    status: 'PENDING'
  };
  claims.unshift(newClaim);
  localStorage.setItem(KEY_CLAIMS, JSON.stringify(claims));
  return newClaim;
};

// --- FINANCIAL SUMMARY ---
export const getFinancialSummary = () => {
  const policies = getPolicies();
  const claims = getClaims();

  const totalGWP = policies.reduce((acc, curr) => acc + curr.premium, 0);
  const totalClaims = claims.reduce((acc, curr) => acc + (curr.status === 'PAID' ? curr.amount : 0), 0);

  return {
    totalGWP,
    totalClaims,
    policyCount: policies.length,
    claimCount: claims.length
  };
};

