    const list = regionPricing[travel.participantType as keyof typeof regionPricing] || regionPricing.INDIVIDUAL;
    const band = list.find((b: any) => currentDuration <= b.maxDays) || list[list.length - 1];

    return band.rates[plan] || 0;
  };

