                </div>
                <div className="flex flex-wrap gap-2">{ben.features.map((f, i) => (<span key={i} className="px-3 py-1 bg-gray-100 dark:bg-white/5 rounded-full text-[0.45rem] font-black uppercase text-gray-500 tracking-widest">{f}</span>))}</div>
                {travel.selectedPlan === p && (<div className="absolute top-4 right-4"><div className="w-6 h-6 bg-primary-500 rounded-full flex items-center justify-center text-white shadow-lg animate-pop-in"><Check size={14} strokeWidth={4}/></div></div>)}
