            <button key={opt.id} onClick={() => setMpar({...mpar, periodMonths: opt.id as any})} className={`p-6 rounded-[2.5rem] border-2 text-left flex items-center gap-6 transition-all ${mpar.periodMonths === opt.id ? 'border-amber-500 bg-amber-500/[0.03] shadow-xl' : 'border-black/5 bg-white dark:bg-white/5 opacity-60'}`}>
