             <div className="flex justify-between items-center text-[0.75rem]"><span className="text-gray-400 font-black uppercase tracking-widest flex items-center gap-3 opacity-80"><Zap size={16} className="text-amber-500"/> Duration</span><span className="font-black text-right uppercase tracking-widest">{mpar.periodMonths} MONTHS</span></div>
