          <div className="pt-8 border-t border-black/5 dark:border-white/5 relative z-10">
              <div className="flex justify-between items-end">
                 <div><p className="text-[0.5rem] font-black uppercase text-gray-400 tracking-widest">Total Premi Net</p><h3 className="text-4xl font-black tracking-tighter text-amber-500">{formatIDR(currentPremium)}</h3></div>
                 <div className="flex flex-col items-end gap-1"><p className="text-[0.45rem] font-black text-emerald-500 uppercase tracking-widest flex items-center gap-1"><Check size={10}/> All Risk Grade</p><p className="text-[0.45rem] font-black text-emerald-500 uppercase tracking-widest flex items-center gap-1"><Check size={10}/> Instant Issue</p></div>
              </div>
          </div>
       </div>
       <button 
         onClick={() => {
            setPayLoading(true);
