                // SAVE DATA
                savePolicy({
                  type: 'PROPERTY',
                  holderName: currentUser?.name || 'GUEST',
                  holderId: currentUser?.ktp || 'N/A',
                  premium: currentPremium,
                  details: `${mpar.category} - ${mpar.itemName} (${mpar.serialNumber})`
                });

                setPayLoading(false);
                onComplete();
            }, 1500);
         }}
         disabled={payLoading}
         className="w-full py-6 bg-gray-900 dark:bg-white text-white dark:text-black rounded-[2rem] font-black uppercase text-base tracking-[0.25em] shadow-2xl flex items-center justify-center gap-4 transition-all hover:scale-[1.02] active:scale-95 disabled:opacity-70 disabled:cursor-not-allowed"
       >
         {payLoading ? <Loader2 className="animate-spin text-amber-500" size={24}/> : <Wallet size={24} className="text-amber-500"/>}
         {payLoading ? 'PROCESSING...' : 'ACTIVATE ASSET SHIELD'}
       </button>
    </div>
  );

  return (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-dark-bg text-gray-900 dark:text-white rounded-[3rem] overflow-hidden border border-black/5 shadow-2xl relative">
       <div className="px-8 pt-8 pb-4 bg-white dark:bg-white/5 border-b border-black/5 flex flex-col gap-6 flex-shrink-0">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
               <div className="w-12 h-12 bg-amber-500 rounded-2xl flex items-center justify-center text-white shadow-xl shadow-amber-500/20 group"><Package size={24} className="group-hover:rotate-12 transition-transform"/></div>
               <div><p className="text-[0.45rem] font-black text-gray-400 uppercase tracking-[0.4em] leading-none mb-1">Matrix Property</p><h3 className="text-lg font-black uppercase tracking-tighter">MPAR All-Risk</h3></div>
            </div>
            <div className="flex bg-gray-100 dark:bg-white/5 p-1 rounded-xl"><div className="px-3 py-1 text-[0.6rem] font-black text-amber-500 uppercase tracking-widest">{STEPS[step]}</div></div>
          </div>
          <div className="flex gap-2">{STEPS.map((s, i) => (<div key={i} className={`h-1.5 rounded-full flex-1 transition-all duration-500 ${i === step ? 'bg-amber-500 shadow-[0_0_10px_rgba(245,158,11,0.4)]' : i < step ? 'bg-amber-500/30' : 'bg-gray-200 dark:bg-white/10'}`}></div>))}</div>
       </div>
       <div className="flex-1 overflow-y-auto p-8 no-scrollbar">
          {step === 0 && renderStep0()}
          {step === 1 && renderStep1()}
          {step === 2 && renderStep2()}
          {step === 3 && renderStep3()}
          {step === 4 && renderStep4()}
       </div>
       <div className="px-8 py-6 bg-white dark:bg-[#111] border-t border-black/5 flex items-center justify-between gap-6 flex-shrink-0">
          <div className="flex-1"><p className="text-[0.55rem] font-black uppercase text-gray-400 leading-none mb-1 tracking-widest">Net Premium</p><p className="text-2xl font-black tracking-tighter text-amber-500">{formatIDR(currentPremium)}</p></div>
          <div className="flex gap-3">
             {step > 0 && (<button onClick={handleBack} className="p-4 bg-gray-100 dark:bg-white/10 rounded-2xl text-gray-500 hover:text-amber-500 transition-colors"><ChevronLeft size={24}/></button>)}
             {step < STEPS.length - 1 && (<button onClick={handleNext} disabled={(step === 1 && (!mpar.itemName || !mpar.itemPrice)) || (step === 3 && !aiScore)} className="px-10 py-4 bg-gray-900 dark:bg-white text-white dark:text-black rounded-2xl font-black uppercase text-[0.7rem] tracking-[0.2em] shadow-2xl transition-all active:scale-95 disabled:opacity-30 flex items-center gap-2">Lanjut <ChevronRight size={18}/></button>)}
          </div>
       </div>
    </div>
  );
};

export default MPARInsuranceWizard;

import React, { useState, useMemo } from 'react';
import { Camera, BrainCircuit, CheckCircle2, Scan, Smartphone, ArrowRight, MapPin, Calendar, Clock, FileText, AlertCircle, Loader2, FileSearch, Trash2, ShieldCheck, ChevronRight, Info, Rocket } from 'lucide-react';
import { analyzeClaimPhoto, summarizeClaimDocument, ClaimAnalysisData, DocumentSummary } from '../services/geminiService';
import { saveClaim } from '../services/dataService';

const formatIDR = (num: number) => {
  return new Intl.NumberFormat('id-ID', {
    style: 'currency', currency: 'IDR', minimumFractionDigits: 0
  }).format(num);
};

interface ReportForm {
  chronology: string;
  location: string;
  date: string;
  time: string;
  thirdPartyInvolved: boolean;
}

const ClaimManager = ({ onComplete }: { onComplete: () => void }) => {
  const [step, setStep] = useState<'upload' | 'analyzing' | 'result' | 'docUpload' | 'docSummary' | 'reporting' | 'success'>('upload');
  const [claimResult, setClaimResult] = useState<ClaimAnalysisData | null>(null);
  const [docSummary, setDocSummary] = useState<DocumentSummary | null>(null);
  const [isSummarizing, setIsSummarizing] = useState(false);
  const [activeTab, setActiveTab] = useState<'evidence' | 'reasoning' | 'steps'>('evidence');

  const [reportForm, setReportForm] = useState<ReportForm>({
    chronology: '',
    location: '',
    date: new Date().toISOString().split('T')[0],
    time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }),
    thirdPartyInvolved: false
  });
  const [isSubmitting, setIsSubmitting] = useState(false);

  const dateLimits = useMemo(() => {
    const today = new Date();
    const max = today.toISOString().split('T')[0];
    const minDate = new Date();
    minDate.setDate(today.getDate() - 7);
    const min = minDate.toISOString().split('T')[0];
    return { min, max };
  }, []);

  const handleClaimUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setStep('analyzing');
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      const response = await analyzeClaimPhoto(base64);
      if (response.success && response.data) {
        setClaimResult(response.data);
        setStep('result');
      } else {
        alert(response.error || 'Audit neural gagal. Mohon gunakan foto yang lebih jelas.');
        setStep('upload');
      }
    };
    reader.readAsDataURL(file);
  };

  const handleDocUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsSummarizing(true);
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      const response = await summarizeClaimDocument(base64);
      setIsSummarizing(false);
      if (response.success && response.data) {
        setDocSummary(response.data);
        setStep('docSummary');
      } else {
        alert(response.error || 'Gagal meringkas dokumen.');
      }
    };
    reader.readAsDataURL(file);
  };

  const handleFinalReport = (e: React.FormEvent) => {
    e.preventDefault();
    if (reportForm.chronology.length < 20) {
      alert("Berikan kronologi lebih detail (min. 20 karakter).");
      return;
    }
    setIsSubmitting(true);
    setTimeout(() => {
      // SAVE CLAIM
      saveClaim({
        policyId: docSummary?.policyNumber || `SP-${Date.now()}`,
        holderName: 'User Node', // In a real app, this comes from session
        type: 'AUTO',
        amount: claimResult?.totalEstimasi || 0,
        riskScore: claimResult?.severity === 'Total Loss' ? 95 : 20
      });

      setIsSubmitting(false);
      setStep('success');
    }, 1500);
  };

  // ... (Header and renders mostly unchanged except for adding saveClaim call above) ...
  const Header = ({ title, showBack = false, onBack = () => {} }: { title: string, showBack?: boolean, onBack?: () => void }) => (
    <div className="flex items-center gap-3 mb-3">
      {showBack && (
        <button onClick={onBack} className="p-2 bg-gray-100 dark:bg-white/5 rounded-full hover:text-primary-500 transition-colors">
          <ChevronRight className="rotate-180" size={16}/>
        </button>
      )}
      <div className="w-7 h-7 bg-primary-500/10 rounded-lg flex items-center justify-center text-primary-500">
        <ShieldCheck size={16}/>
      </div>
      <h3 className="text-lg font-black uppercase tracking-tight">{title}</h3>
    </div>
  );

  if (step === 'upload') {
    return (
      <div className="space-y-3 animate-fade-in flex flex-col h-full justify-center">
        <div className="aspect-[4/3] relative rounded-[2rem] overflow-hidden bg-gray-100 dark:bg-white/5 border-2 border-dashed border-primary-500/30 flex flex-col items-center justify-center group cursor-pointer shadow-inner">
          <div className="w-14 h-14 bg-primary-500/10 rounded-full flex items-center justify-center text-primary-500 mb-2 group-hover:scale-110 transition-transform">
            <Camera size={28} />
          </div>
          <p className="text-base font-black uppercase text-gray-400 group-hover:text-primary-500 transition-colors tracking-tight">Accelerate Audit</p>
          <p className="text-[0.5rem] text-gray-400 mt-1 font-bold uppercase tracking-widest text-center px-4">Instant visual damage appraisal for express submission</p>
          <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleClaimUpload} />
        </div>
        <div className="grid grid-cols-2 gap-2">
          <div className="p-3 rounded-xl bg-white dark:bg-white/5 border border-black/5 flex flex-col items-center text-center gap-1.5"><Scan size={18} className="text-primary-500" /><p className="text-[0.45rem] font-black uppercase tracking-widest text-gray-500">Fraud Detection</p></div>
          <div className="p-3 rounded-xl bg-white dark:bg-white/5 border border-black/5 flex flex-col items-center text-center gap-1.5"><Rocket size={18} className="text-primary-500" /><p className="text-[0.45rem] font-black uppercase tracking-widest text-gray-500">Express Submit</p></div>
        </div>
      </div>
    );
  }

  if (step === 'analyzing') {
    return (
      <div className="glass-card rounded-[2rem] p-6 animate-pop-in text-center space-y-4 flex flex-col h-full justify-center">
        <div className="relative w-16 h-16 mx-auto">
          <div className="absolute inset-0 bg-primary-500/20 rounded-full animate-ping"></div>
          <div className="relative w-16 h-16 bg-primary-500/10 rounded-full flex items-center justify-center border-2 border-primary-500/30"><BrainCircuit size={32} className="text-primary-500 animate-pulse" /></div>
        </div>
        <div className="space-y-1">
          <p className="text-[0.55rem] font-black uppercase text-primary-500 tracking-[0.4em] animate-pulse">Initializing Audit Mesh...</p>
          <p className="text-[0.45rem] text-gray-400 uppercase font-bold tracking-widest">Accelerating Submission Logic</p>
          <div className="w-32 h-1 bg-gray-200 dark:bg-white/10 mx-auto rounded-full overflow-hidden mt-3"><div className="h-full bg-primary-500 animate-shimmer" style={{ width: '70%' }}></div></div>
        </div>
      </div>
    );
  }

  if (step === 'result' && claimResult) {
    return (
      <div className="space-y-3 animate-pop-in h-full flex flex-col pb-2">
        <div className="p-4 glass-card rounded-[2rem] border-2 border-primary-500/20 bg-primary-500/5 relative overflow-hidden flex-shrink-0">
          <div className="absolute top-3 right-3"><div className="px-2 py-0.5 bg-primary-500 text-white rounded-md font-black text-[0.45rem] uppercase tracking-widest">{claimResult.severity} Damage</div></div>
          <p className="text-[0.45rem] font-black uppercase text-primary-500 tracking-[0.3em] mb-1">Pre-validated Claim Appraisal</p>
          <h3 className="text-3xl font-black tracking-tighter mb-1">{formatIDR(claimResult.totalEstimasi)}</h3>
          <p className="text-[0.6rem] font-bold text-gray-600 dark:text-gray-300 leading-tight border-l-2 border-primary-500 pl-2">AI Speed Insight: {claimResult.aiInsight}</p>
        </div>
        <div className="flex bg-gray-100 dark:bg-white/5 p-0.5 rounded-lg text-[0.5rem] font-black uppercase tracking-widest">
            <button onClick={() => setActiveTab('evidence')} className={`flex-1 py-1.5 rounded-md transition-all ${activeTab === 'evidence' ? 'bg-white dark:bg-gray-700 shadow-sm text-primary-500' : 'text-gray-400'}`}>Visual Analysis</button>
            <button onClick={() => setActiveTab('reasoning')} className={`flex-1 py-1.5 rounded-md transition-all ${activeTab === 'reasoning' ? 'bg-white dark:bg-gray-700 shadow-sm text-primary-500' : 'text-gray-400'}`}>Tech Summary</button>
            <button onClick={() => setActiveTab('steps')} className={`flex-1 py-1.5 rounded-md transition-all ${activeTab === 'steps' ? 'bg-white dark:bg-gray-700 shadow-sm text-primary-500' : 'text-gray-400'}`}>Express Track</button>
        </div>
        <div className="flex-1 overflow-y-auto pr-0.5 no-scrollbar min-h-0">
          {activeTab === 'evidence' && (
            <div className="animate-fade-in space-y-2 p-1">
              {claimResult.rincianPart && claimResult.rincianPart.length > 0 ? (
                claimResult.rincianPart.map((p, i) => (
                  <div key={i} className="p-3 bg-white dark:bg-white/5 rounded-xl border border-black/5 flex items-center justify-between shadow-sm">
                    <div className="flex-1"><p className="font-black uppercase text-[0.6rem] tracking-tight">{p.namaPart}</p><p className="text-[0.45rem] font-bold text-gray-400 uppercase tracking-widest mt-0.5">{p.kondisi}</p></div>
                    <div className="text-right ml-4"><p className="font-black text-[0.7rem] text-primary-500 leading-none">{formatIDR(p.estimasiBiaya)}</p><div className={`mt-1.5 text-[0.45rem] font-black uppercase tracking-widest px-2 py-0.5 rounded flex items-center gap-1 ${p.tindakan === 'Ganti' ? 'bg-rose-500/10 text-rose-500' : 'bg-blue-500/10 text-blue-500'}`}>{p.tindakan === 'Ganti' ? <Trash2 size={8}/> : <Wrench size={8}/>}{p.tindakan}</div></div>
                  </div>
                ))
              ) : (
                <div className="p-6 text-center space-y-2 bg-gray-50 dark:bg-white/5 rounded-2xl border border-dashed border-gray-200 dark:border-white/10"><Info size={24} className="mx-auto text-gray-300"/><p className="text-[0.55rem] font-black uppercase text-gray-400">Scan unit untuk memvalidasi rincian klaim.</p></div>
              )}
            </div>
          )}
          {activeTab === 'reasoning' && (
            <div className="animate-fade-in space-y-3 p-1">
                <div className="bg-primary-500/5 p-4 rounded-xl border border-primary-500/10"><p className="text-[0.5rem] font-black uppercase text-primary-500 mb-2 tracking-widest flex items-center gap-2"><BrainCircuit size={10}/> Submission Logic Engine</p><p className="text-[0.65rem] text-gray-600 dark:text-gray-300 leading-relaxed font-medium">{claimResult.technicalReasoning}</p></div>
                <div className="bg-gray-50 dark:bg-white/5 p-4 rounded-xl border border-gray-100 dark:border-white/5"><p className="text-[0.5rem] font-black uppercase text-gray-400 mb-2 tracking-widest">Recommended Rapid Workshop</p><p className="text-[0.65rem] font-bold uppercase tracking-tight text-gray-900 dark:text-white flex items-center gap-2"><MapPin size={10} className="text-primary-500"/> {claimResult.rekomendasiBengkel}</p></div>
            </div>
          )}
          {activeTab === 'steps' && (
            <div className="animate-fade-in space-y-2 p-1">
                {claimResult.nextSteps.map((step, idx) => (
                    <div key={idx} className="flex gap-3 p-3 bg-emerald-50 dark:bg-emerald-950/20 rounded-xl border border-emerald-100 dark:border-emerald-900/30 items-center">
                        <div className="w-5 h-5 bg-emerald-500 text-white rounded-lg flex items-center justify-center flex-shrink-0 text-[0.6rem] font-black">{idx + 1}</div>
                        <p className="text-[0.6rem] font-bold text-emerald-900 dark:text-emerald-100 uppercase tracking-tight">{step}</p>
                    </div>
                ))}
            </div>
          )}
        </div>
        <div className="grid grid-cols-2 gap-2 pt-1 flex-shrink-0">
          <button onClick={() => setStep('docUpload')} className="py-3 bg-white dark:bg-white/5 border border-black/5 rounded-xl font-black uppercase text-[0.55rem] tracking-widest flex items-center justify-center gap-1.5 transition-all active:scale-95 shadow-sm"><FileSearch size={14}/> Fast Doc Scan</button>
          <button onClick={() => setStep('reporting')} className="py-3 bg-primary-500 text-white rounded-xl font-black uppercase text-[0.55rem] tracking-widest shadow-lg shadow-primary-500/20 transition-all active:scale-95">Lanjut Lapor Cepat</button>
        </div>
      </div>
    );
  }

  if (step === 'docUpload') {
    return (
      <div className="space-y-4 animate-fade-in flex flex-col h-full justify-center">
        <Header title="Accelerated Document Audit" showBack onBack={() => setStep('result')} />
        <div className="p-6 rounded-[2rem] border-2 border-dashed border-gray-300 dark:border-white/10 flex flex-col items-center justify-center text-center gap-3 relative bg-gray-50 dark:bg-white/5">
          {isSummarizing ? (
            <div className="py-6 space-y-3"><Loader2 className="animate-spin text-primary-500 mx-auto" size={28}/><p className="text-[0.55rem] font-black uppercase text-gray-400 animate-pulse">Syncing to Insurer...</p></div>
          ) : (
            <>
              <FileSearch size={32} className="text-gray-300"/>
              <div className="space-y-0.5"><p className="font-black text-xs uppercase tracking-tight">Rapid Document Upload</p><p className="text-[0.45rem] font-bold text-gray-400 uppercase tracking-widest">Instant data extraction for claim speed</p></div>
              <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleDocUpload} />
            </>
          )}
        </div>
        {!isSummarizing && <button onClick={() => setStep('result')} className="w-full py-3 text-[0.5rem] font-black uppercase text-gray-400 tracking-widest">Kembali ke Audit</button>}
      </div>
    );
  }

  if (step === 'docSummary' && docSummary) {
    return (
      <div className="space-y-3 animate-pop-in h-full flex flex-col">
        <Header title="Neural Submission Summary" showBack onBack={() => setStep('docUpload')} />
        <div className="p-4 bg-primary-500/5 border border-primary-500/20 rounded-xl space-y-1">
          <p className="text-[0.4rem] font-black text-primary-500 uppercase tracking-widest">Express Path Policy</p>
          <p className="font-black text-base tracking-tight uppercase">{docSummary.policyNumber}</p>
        </div>
        <div className="flex-1 overflow-y-auto space-y-3 no-scrollbar pr-1">
          <div className="space-y-1.5"><p className="text-[0.5rem] font-black uppercase text-gray-400 ml-1">Pre-Validated Data</p><div className="grid gap-1.5">{docSummary.keyPoints.map((point, i) => (<div key={i} className="flex gap-2 p-2.5 bg-white dark:bg-white/5 border border-black/5 rounded-xl text-[0.6rem] font-medium items-start"><div className="w-3 h-3 rounded-full bg-emerald-500/10 flex items-center justify-center text-emerald-500 flex-shrink-0 mt-0.5"><CheckCircle2 size={8}/></div>{point}</div>))}</div></div>
          <div className="p-3 bg-gray-100 dark:bg-white/5 rounded-xl space-y-1 border border-black/5"><p className="text-[0.45rem] font-black uppercase text-gray-400">Submission Risk Level</p><p className="text-[0.6rem] italic font-bold leading-snug">{docSummary.riskAssessment}</p></div>
        </div>
        <div className="grid grid-cols-2 gap-2 pt-2">
          <button onClick={() => setStep('docUpload')} className="py-3 bg-white dark:bg-white/5 border border-black/5 rounded-xl font-black uppercase text-[0.5rem] tracking-widest">Rescan Docs</button>
          <button onClick={() => setStep('reporting')} className="py-3 bg-primary-500 text-white rounded-xl font-black uppercase text-[0.5rem] tracking-widest shadow-lg">Confirm Submission</button>
        </div>
      </div>
    );
  }

  if (step === 'reporting') {
    return (
      <div className="animate-fade-in flex flex-col h-full">
        <Header title="Express Incident Report" showBack onBack={() => setStep('result')} />
        <form onSubmit={handleFinalReport} className="flex-1 overflow-y-auto pr-1 no-scrollbar space-y-3">
          <div className="grid grid-cols-2 gap-2">
            <div className="space-y-1"><label className="text-[0.45rem] font-black uppercase tracking-widest text-gray-400 ml-1">Tanggal (Kejadian)</label><div className="relative"><Calendar size={12} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-primary-500 pointer-events-none" /><input type="date" required min={dateLimits.min} max={dateLimits.max} className="w-full pl-8 pr-2 py-2.5 rounded-xl bg-white dark:bg-white/5 border border-black/5 text-[0.65rem] outline-none focus:border-primary-500 font-bold" value={reportForm.date} onChange={(e) => setReportForm({...reportForm, date: e.target.value})}/></div></div>
