          </div>
          <div className="space-y-1"><label className="text-[0.45rem] font-black uppercase tracking-widest text-gray-400 ml-1">Lokasi TKP</label><div className="relative"><MapPin size={12} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-primary-500" /><input type="text" required placeholder="Alamat detail..." className="w-full pl-8 pr-2 py-2.5 rounded-xl bg-white dark:bg-white/5 border border-black/5 text-[0.65rem] outline-none focus:border-primary-500 font-bold" value={reportForm.location} onChange={(e) => setReportForm({...reportForm, location: e.target.value})}/></div></div>
          <div className="space-y-1"><label className="text-[0.45rem] font-black uppercase tracking-widest text-gray-400 ml-1">Kronologi Singkat</label><textarea required rows={3} placeholder="Apa yang terjadi secara detail?" className="w-full px-3 py-2.5 rounded-xl bg-white dark:bg-white/5 border border-black/5 text-[0.6rem] outline-none focus:border-primary-500 resize-none font-medium leading-tight shadow-inner" value={reportForm.chronology} onChange={(e) => setReportForm({...reportForm, chronology: e.target.value})}/></div>
        </form>
        <button onClick={handleFinalReport} disabled={isSubmitting} className="mt-2 w-full py-4 bg-gray-900 dark:bg-white text-white dark:text-black rounded-xl font-black uppercase text-[0.55rem] tracking-[0.2em] shadow-xl flex items-center justify-center gap-2 disabled:opacity-50 transition-all active:scale-95">{isSubmitting ? <Loader2 className="animate-spin" size={14}/> : <Rocket size={14}/>} Kirim Klaim Kilat</button>
      </div>
