  }

  if (step === 'success') {
    return (
      <div className="text-center space-y-4 py-4 animate-pop-in flex flex-col h-full justify-center">
        <div className="w-20 h-20 bg-emerald-500 rounded-full mx-auto flex items-center justify-center text-white shadow-2xl shadow-emerald-500/30"><CheckCircle2 size={40} strokeWidth={3} /></div>
