    setLoading(true);
    setLoadingType('STNK');

    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      setSurvey(prev => ({ ...prev, stnk: base64 }));

      try {
        const res = await extractStnkData(base64);
        if (res.success && res.data) {
          setStnkResult({
            ownerName: 'USER', // AI extraction placeholder
            plate: res.data.plate || '',
            vin: res.data.vin || '',
            engine: res.data.engine || '',
            color: '', 
            year: res.data.year || '',
            status: res.data.status || 'OK'
          });
          setVehicle(prev => ({ ...prev, plate: res.data.plate || prev.plate, year: parseInt(res.data.year) || prev.year }));
        }
      } catch (err) {
        console.error(err);
      }
      setLoading(false);
    };
    reader.readAsDataURL(file);
  };

  const runSurveyAI = async () => {
    if (!survey.stnk || Object.keys(survey.photos).length < 1) return;
    setLoading(true);
    setLoadingType('SURVEY');

    try {
      // Prepare images
      const images = Object.entries(survey.photos).map(([id, data]) => ({ id, data }));
      // Also add STNK
      images.push({ id: 'stnk', data: survey.stnk! });

      const res = await analyzeVehicleSurvey(images);

