} from 'lucide-react';
import { MPARState, MPARCategory } from '../types';
import { MPAR_PRICING } from '../constants';
import { savePolicy } from '../services/dataService';
import { analyzeClaimPhoto } from '../services/geminiService';

const formatIDR = (n: number) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', minimumFractionDigits: 0 }).format(n);

const STEPS = ['Asset Detail', 'Condition Audit', 'Review & Pay'];

const MPARInsuranceWizard = ({ onComplete, currentUser }: { onComplete: () => void, currentUser?: any }) => {
  const [step, setStep] = useState(0);
  const [payLoading, setPayLoading] = useState(false);
  const [analyzing, setAnalyzing] = useState(false);
  const [aiScore, setAiScore] = useState<number | null>(null);

  const [mpar, setMpar] = useState<MPARState>({
    category: 'GADGET',
    subCategory: 'SMARTPHONE',
    itemName: '',
    itemPrice: 0,
    itemAge: 0,
    serialNumber: '',
    periodMonths: 12
  });

  const [photos, setPhotos] = useState<{ front?: string }>({});

  const handleNext = () => setStep(s => Math.min(s + 1, STEPS.length - 1));
  const handleBack = () => setStep(s => Math.max(s - 1, 0));

  const calculatePremium = () => {
    // Simple logic based on category and price range from MPAR_PRICING
    let pricingList: any[] = [];
    if (mpar.category === 'ELECTRONIC') pricingList = MPAR_PRICING.ELECTRONIC;
    else if (mpar.category === 'FURNITURE') pricingList = MPAR_PRICING.FURNITURE;
    else if (mpar.category === 'GADGET') {
      pricingList = mpar.periodMonths === 12 ? MPAR_PRICING.GADGET.MONTHS_12 : MPAR_PRICING.GADGET.MONTHS_6;
    }

    if (!pricingList.length) return 0;

    const band = pricingList.find((b: any) => mpar.itemPrice >= b.min && mpar.itemPrice <= b.max) || pricingList[pricingList.length - 1];

    if (mpar.category === 'ELECTRONIC') {
        return mpar.subCategory === 'TV' ? band.TV : band.NON_TV;
    }

    return band.premium || 0;
  };

  const runAiAudit = async () => {
    if (!photos.front) return;
    setAnalyzing(true);
    // Reuse claim analysis for condition check (severity logic inverse)
    const res = await analyzeClaimPhoto(photos.front);
    if (res.success && res.data) {
        // Mocking score derivation from claim result. If severity is low, score is high.
        let score = 95;
        if (res.data.severity === 'Sedang') score = 70;
        if (res.data.severity === 'Berat') score = 40;
        if (res.data.severity === 'Total Loss') score = 10;
        setAiScore(score);
    } else {
        setAiScore(85); // Fallback mock
    }
    setAnalyzing(false);
  };

  const renderStep0 = () => (
    <div className="space-y-6 animate-fade-in">
        <div className="p-4 bg-amber-500/10 rounded-3xl border border-amber-500/20 flex gap-4">
