            <p className="text-[0.65rem] font-bold text-gray-600 dark:text-gray-300 leading-relaxed uppercase tracking-wider">
            Mobile Property All Risk. Protect gadgets, electronics, and furniture.
            </p>
        </div>
        <div className="grid grid-cols-1 gap-4">
            {[ { id: 'GADGET', label: 'Gadget Protection', icon: Smartphone }, { id: 'ELECTRONIC', label: 'Electronic Shield', icon: Monitor }, { id: 'FURNITURE', label: 'Furniture Guard', icon: Armchair } ].map(cat => (
                <button key={cat.id} onClick={() => setMpar({...mpar, category: cat.id as any})} className={`p-6 rounded-[2.5rem] border-2 text-left flex items-center gap-6 transition-all ${mpar.category === cat.id ? 'border-amber-500 bg-amber-500/[0.03] shadow-xl' : 'border-black/5 bg-white dark:bg-white/5 opacity-60'}`}>
                    <div className={`w-14 h-14 rounded-2xl flex items-center justify-center bg-gray-100 dark:bg-white/10 ${mpar.category === cat.id ? 'text-amber-500' : 'text-gray-400'}`}><cat.icon size={28}/></div>
                    <div><h4 className="font-black text-lg uppercase tracking-tighter">{cat.label}</h4></div>
                    {mpar.category === cat.id && <Check className="ml-auto text-amber-500" size={24} strokeWidth={3}/>}
                </button>
            ))}
        </div>
        <div className="space-y-4">
            <div className="space-y-1"><label className="text-[0.5rem] font-black uppercase text-gray-400 ml-1">Item Name</label><input className="w-full px-5 py-4 rounded-2xl bg-white dark:bg-white/5 border-2 border-black/5 outline-none focus:border-amber-500 font-black text-sm uppercase" value={mpar.itemName} onChange={e => setMpar({...mpar, itemName: e.target.value})} placeholder="IPHONE 15 PRO"/></div>
            <div className="space-y-1"><label className="text-[0.5rem] font-black uppercase text-gray-400 ml-1">Price (IDR)</label><input type="number" className="w-full px-5 py-4 rounded-2xl bg-white dark:bg-white/5 border-2 border-black/5 outline-none focus:border-amber-500 font-black text-sm" value={mpar.itemPrice} onChange={e => setMpar({...mpar, itemPrice: parseInt(e.target.value)})}/></div>
        </div>
    </div>
  );

  const renderStep1 = () => (
    <div className="space-y-6 animate-fade-in">
       <div className="p-6 bg-white dark:bg-white/5 rounded-[2.5rem] border-2 border-black/5 shadow-xl relative overflow-hidden">
          <div className="space-y-2"><h4 className="text-2xl font-black uppercase tracking-tighter">Neural Item Audit</h4><p className="text-[0.65rem] font-bold text-gray-500 uppercase tracking-widest">Scan your asset for condition verification.</p></div>
          <div className="grid grid-cols-1 gap-4 pt-4">
             {photos.front ? (
                <div className="relative aspect-video rounded-3xl overflow-hidden group">
                   <img src={photos.front} className="w-full h-full object-cover" />
                   <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-all flex flex-col items-center justify-center gap-4"><button onClick={() => setPhotos({})} className="p-3 bg-white text-rose-500 rounded-2xl shadow-xl"><Trash2 size={24}/></button><button onClick={runAiAudit} className="px-6 py-2.5 bg-amber-500 text-white rounded-xl font-black uppercase text-[0.6rem] tracking-widest">Retest Audit</button></div>
                   {aiScore && (<div className="absolute top-4 right-4 bg-emerald-500 text-white px-3 py-1 rounded-lg font-black text-[0.6rem] uppercase shadow-2xl border border-white/20">Score: {aiScore}% Clean</div>)}
                </div>
             ) : (
                <label className="aspect-video rounded-[2.5rem] border-2 border-dashed border-gray-300 dark:border-white/10 bg-gray-50 dark:bg-white/5 flex flex-col items-center justify-center gap-3 cursor-pointer group hover:border-amber-500/50 transition-all">
                   <div className="w-12 h-12 rounded-2xl bg-white dark:bg-white/10 flex items-center justify-center shadow-md group-hover:scale-110 transition-transform"><Camera size={24} className="text-gray-400 group-hover:text-amber-500"/></div>
                   <p className="text-[0.55rem] font-black uppercase text-gray-400 tracking-widest">Upload Front View (Live)</p>
                   <input type="file" accept="image/*" className="hidden" onChange={(e) => { const file = e.target.files?.[0]; if (!file) return; const reader = new FileReader(); reader.onload = () => setPhotos({...photos, front: reader.result as string}); reader.readAsDataURL(file); }} />
                </label>
             )}
          </div>
       </div>
       {photos.front && !aiScore && (
         <button onClick={runAiAudit} disabled={analyzing} className="w-full py-4 bg-amber-500 text-white rounded-2xl font-black uppercase text-[0.6rem] tracking-widest shadow-lg active:scale-95 transition-all flex items-center justify-center gap-3">
            {analyzing ? <Loader2 className="animate-spin" size={18}/> : <ShieldCheck size={18}/>} Analyze Condition
         </button>
       )}
    </div>
  );

  const renderReview = () => (
    <div className="space-y-6 animate-fade-in pb-20">
       <div className="p-8 bg-white dark:bg-white/5 rounded-[3rem] border-2 border-black/5 space-y-8 shadow-xl relative overflow-hidden">
          <div className="absolute right-0 top-0 p-10 opacity-[0.03] dark:opacity-[0.06] -rotate-12 translate-x-12 -translate-y-12"><Package size={200}/></div>
          <div className="flex justify-between items-start relative z-10">
             <div><p className="text-[0.6rem] font-black uppercase text-gray-400 tracking-[0.4em] mb-1.5 opacity-80">Protection Matrix</p><h4 className="text-3xl font-black uppercase tracking-tighter text-amber-500">{mpar.itemName}</h4></div>
             <div className="p-4 bg-amber-500/10 rounded-2xl text-amber-500 shadow-inner"><ShieldCheck size={24}/></div>
          </div>
          <div className="grid grid-cols-1 gap-5 pt-6 border-t border-black/5 dark:border-white/5 relative z-10">
             <div className="flex justify-between items-center text-[0.75rem]"><span className="text-gray-400 font-black uppercase tracking-widest">Category</span><span className="font-black text-right uppercase">{mpar.category}</span></div>
