          </div>
          <div className="pt-8 border-t border-black/5 dark:border-white/5 relative z-10">
              <div className="flex justify-between items-end">
                 <div><p className="text-[0.5rem] font-black uppercase text-gray-400 tracking-widest">Total Premi Net</p><h3 className="text-4xl font-black tracking-tighter text-amber-500">{formatIDR(calculatePremium())}</h3></div>
                 <div className="flex flex-col items-end gap-1"><p className="text-[0.45rem] font-black text-emerald-500 uppercase tracking-widest flex items-center gap-1"><Check size={10}/> Instant Issue</p></div>
              </div>
          </div>
       </div>
       <button 
         onClick={() => {
            setPayLoading(true);
            setTimeout(() => {
                savePolicy({
                  type: 'PROPERTY',
                  holderName: currentUser?.name || 'USER',
                  holderId: currentUser?.ktp || 'N/A',
                  premium: calculatePremium(),
                  details: `${mpar.category}: ${mpar.itemName}`
                });
                setPayLoading(false);
                onComplete();
            }, 1500);
         }}
         disabled={payLoading}
         className="w-full py-6 bg-gray-900 dark:bg-white text-white dark:text-black rounded-[2rem] font-black uppercase text-base tracking-[0.25em] shadow-2xl flex items-center justify-center gap-4 transition-all hover:scale-[1.02] active:scale-95 disabled:opacity-70 disabled:cursor-not-allowed"
       >
         {payLoading ? <Loader2 className="animate-spin text-amber-500" size={24}/> : <Wallet size={24} className="text-amber-500"/>}
         {payLoading ? 'PROCESSING...' : 'ACTIVATE PROTECTION'}
       </button>
    </div>
  );

  return (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-dark-bg text-gray-900 dark:text-white rounded-[3rem] overflow-hidden border border-black/5 shadow-2xl relative">
       <div className="px-8 pt-8 pb-4 bg-white dark:bg-white/5 border-b border-black/5 flex flex-col gap-6 flex-shrink-0">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
               <div className="w-12 h-12 bg-amber-500 rounded-2xl flex items-center justify-center text-white shadow-xl shadow-amber-500/20 group"><Package size={24} className="group-hover:rotate-12 transition-transform"/></div>
               <div><p className="text-[0.45rem] font-black text-gray-400 uppercase tracking-[0.4em] leading-none mb-1">Matrix Property</p><h3 className="text-lg font-black uppercase tracking-tighter">Mobile All Risk</h3></div>
            </div>
            <div className="flex bg-gray-100 dark:bg-white/5 p-1 rounded-xl"><div className="px-3 py-1 text-[0.6rem] font-black text-amber-500 uppercase tracking-widest">{STEPS[step]}</div></div>
          </div>
