       <div className="px-8 py-6 bg-white dark:bg-[#111] border-t border-black/5 flex items-center justify-between gap-6 flex-shrink-0">
          <div className="flex-1"><p className="text-[0.55rem] font-black uppercase text-gray-400 leading-none mb-1 tracking-widest">Premium</p><p className="text-2xl font-black tracking-tighter text-amber-500">{formatIDR(calculatePremium())}</p></div>
          <div className="flex gap-3">
             {step > 0 && (<button onClick={handleBack} className="p-4 bg-gray-100 dark:bg-white/10 rounded-2xl text-gray-500 hover:text-amber-500 transition-colors"><ChevronLeft size={24}/></button>)}
             {step < STEPS.length - 1 && (<button onClick={handleNext} disabled={(step === 0 && !mpar.itemPrice)} className="px-10 py-4 bg-gray-900 dark:bg-white text-white dark:text-black rounded-2xl font-black uppercase text-[0.7rem] tracking-[0.2em] shadow-2xl transition-all active:scale-95 disabled:opacity-30 flex items-center gap-2">Lanjut <ChevronRight size={18}/></button>)}
          </div>
       </div>
    </div>
  );
};

