  </div>
);

const CarInsuranceWizard = ({ onComplete, currentUser }: { onComplete: () => void, currentUser?: any }) => {
  const [loading, setLoading] = useState(false);
  const [loadingType, setLoadingType] = useState<'STNK' | 'SURVEY' | ''>('');
  const [hasProKey, setHasProKey] = useState(false);

  const [survey, setSurvey] = useState<{
    stnk: string | null;
    photos: Record<string, string>;
    score: number;
    verdict: string;
    summary: string;
    detailedIssues: any[];
    photoFlags: any[];
    underwritingChecks: any[];
    manualVerif: boolean;
  }>({
    stnk: null,
    photos: {},
    score: 0,
    verdict: '',
    summary: '',
    detailedIssues: [],
    photoFlags: [],
    underwritingChecks: [],
    manualVerif: false
  });

  const [stnkResult, setStnkResult] = useState({
    ownerName: '',
    plate: '',
    vin: '',
    engine: '',
    color: '',
    year: '',
    status: ''
  });

  const handleStnkUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setLoading(true);
    setLoadingType('STNK');

    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      setSurvey(prev => ({ ...prev, stnk: base64 }));

      const res = await extractStnkData(base64);
      if (res.success && res.data) {
        setStnkResult({
          ownerName: res.data.ownerName || '',
          plate: res.data.plate || '',
          vin: res.data.vin || '',
          engine: res.data.engine || '',
          color: res.data.color || '',
          year: res.data.year || '',
          status: res.data.status || 'OK'
        });
      }
      setLoading(false);
      setLoadingType('');
    };
    reader.readAsDataURL(file);
  };

  const runSurveyAI = async () => {
    if (Object.keys(survey.photos).length < 1) return;

    if ((window as any).aistudio) {
        try {
            const hasKey = await (window as any).aistudio.hasSelectedApiKey();
            if (!hasKey) {
                setHasProKey(false);
                return;
            }
            setHasProKey(true);
        } catch(e) {
            console.error(e);
        }
    } else {
        setHasProKey(true); 
    }

    setLoading(true);
    setLoadingType('SURVEY');

    const images = Object.entries(survey.photos).map(([id, data]) => ({ id, data }));
    const res = await analyzeVehicleSurvey(images);

    if (res.success) {
      setSurvey(prev => ({
        ...prev,
        score: res.score || 0,
        verdict: res.auditVerdict || 'REVIEW_REQUIRED',
        summary: res.summary || '',
        detailedIssues: res.detailedIssues || [],
        photoFlags: res.photoFlags || [],
        underwritingChecks: res.underwritingChecks || [],
        manualVerif: res.auditVerdict === 'REVIEW_REQUIRED' || (res.score !== undefined && res.score < 60)
      }));
    } else {
      if (res.error?.includes('AUTH_REQUIRED') || res.error?.includes('Pro model key')) {
         setHasProKey(false);
      } else {
         alert(res.error);
      }
    }
    setLoading(false);
    setLoadingType('');
  };

  const renderStepSurvey = () => {
    const photoSlots = [{ id: 'front', label: 'Front 45°', desc: 'Depan Serong' }, { id: 'back', label: 'Rear 45°', desc: 'Belakang Serong' }, { id: 'right', label: 'Right Side', desc: 'Sisi Kanan' }, { id: 'left', label: 'Left Side', desc: 'Sisi Kiri' }, { id: 'interior', label: 'Dashboard', desc: 'Interior Depan' }];
    const capturedCount = Object.keys(survey.photos).length;
    const verdictData: any = {
      'CLEAN': { icon: ShieldCheck, color: 'text-emerald-500', bg: 'bg-emerald-500/10', label: 'AUDIT PASSED', desc: 'Skor neural di atas ambang batas. Polis dapat diaktifkan secara instan.' },
      'REVIEW_REQUIRED': { icon: Activity, color: 'text-amber-500', bg: 'bg-amber-500/10', label: 'MANUAL REVIEW', desc: 'Skor audit < 85 atau anomali minor terdeteksi. Memerlukan approval manual oleh admin HQ.' },
      'REJECTED': { icon: ShieldX, color: 'text-rose-500', bg: 'bg-rose-500/10', label: 'REJECTED', desc: 'Kerusakan kritis atau indikasi fraud berat terdeteksi oleh sistem.' },
    };

    return (
      <div className="space-y-8 animate-fade-in pb-24">
        <div className="p-6 bg-white dark:bg-white/[0.03] border-2 border-black/5 dark:border-white/5 rounded-[2.5rem] space-y-6 shadow-xl relative overflow-hidden">
           <div className="flex items-center gap-4 mb-2">
              <div className="w-10 h-10 bg-primary-500/10 rounded-xl flex items-center justify-center text-primary-500 shadow-inner"><FileText size={20}/></div>
              <div><h4 className="text-[0.7rem] font-black uppercase tracking-[0.2em]">Registrasi STNK AI</h4><p className="text-[0.5rem] font-bold text-gray-400 uppercase tracking-widest">Neural Document Extraction</p></div>
           </div>
