                {loading && loadingType === 'STNK' ? <ScannerOverlay label="STNK Neural Audit" /> : (
                  <><FileSearch size={32} className="text-gray-300 group-hover:text-primary-500 transition-colors"/><p className="text-[0.6rem] font-black uppercase tracking-[0.2em] text-gray-500">Scan Dokumen STNK</p><input type="file" accept="image/*" className="hidden" onChange={handleStnkUpload} /></>
                )}
