                   </div>
                   <div className="flex-1 space-y-3">
                      <div className="space-y-1"><label className="text-[0.45rem] font-black uppercase text-gray-400 flex items-center gap-1"><User size={8}/> Pemilik STNK</label><input className="w-full bg-gray-100 dark:bg-white/5 px-3 py-2 rounded-lg text-[0.65rem] font-black uppercase outline-none focus:ring-1 focus:ring-primary-500" value={stnkResult.ownerName} onChange={(e) => setStnkResult({...stnkResult, ownerName: e.target.value.toUpperCase()})} /></div>
                      <div className="grid grid-cols-2 gap-2">
                        <div className="space-y-1"><label className="text-[0.45rem] font-black uppercase text-gray-400">Plat No</label><input className="w-full bg-gray-100 dark:bg-white/5 px-3 py-2 rounded-lg text-[0.65rem] font-black uppercase" value={stnkResult.plate} onChange={(e) => setStnkResult({...stnkResult, plate: e.target.value.toUpperCase()})} /></div>
                        <div className="space-y-1"><label className="text-[0.45rem] font-black uppercase text-gray-400">Warna</label><input className="w-full bg-gray-100 dark:bg-white/5 px-3 py-2 rounded-lg text-[0.65rem] font-black uppercase" value={stnkResult.color} onChange={(e) => setStnkResult({...stnkResult, color: e.target.value.toUpperCase()})} /></div>
                      </div>
                   </div>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1"><label className="text-[0.45rem] font-black uppercase text-gray-400">No Rangka (VIN)</label><input className="w-full bg-gray-100 dark:bg-white/5 px-3 py-2 rounded-lg text-[0.65rem] font-mono font-black uppercase" value={stnkResult.vin} onChange={(e) => setStnkResult({...stnkResult, vin: e.target.value.toUpperCase()})} /></div>
                  <div className="space-y-1"><label className="text-[0.45rem] font-black uppercase text-gray-400">No Mesin</label><input className="w-full bg-gray-100 dark:bg-white/5 px-3 py-2 rounded-lg text-[0.65rem] font-mono font-black uppercase" value={stnkResult.engine} onChange={(e) => setStnkResult({...stnkResult, engine: e.target.value.toUpperCase()})} /></div>
                </div>
             </div>
           )}
        </div>
        <div className="space-y-4">
          <div className="flex items-center justify-between px-2"><div className="flex items-center gap-3"><Camera size={16} className="text-primary-500"/><h4 className="text-[0.7rem] font-black uppercase tracking-[0.2em] text-gray-500">Visual Evidence Matrix</h4></div><div className="px-3 py-1 bg-primary-500/10 rounded-full text-[0.5rem] font-black text-primary-500 uppercase">{capturedCount}/5 Done</div></div>
          <div className="grid grid-cols-2 gap-4">
             {photoSlots.map((slot) => (
                <div key={slot.id} className={`group relative aspect-video rounded-[2rem] border-2 border-dashed transition-all flex flex-col items-center justify-center p-4 text-center gap-2 overflow-hidden shadow-sm ${survey.photos[slot.id] ? 'border-primary-500 bg-primary-500/[0.03] border-solid' : 'border-black/10 dark:border-white/10 bg-white dark:bg-white/[0.03]'}`}>
                   {survey.photos[slot.id] ? (
                     <><img src={survey.photos[slot.id]} className="absolute inset-0 w-full h-full object-cover rounded-[1.8rem]" alt={slot.label} /><button onClick={() => { const newPhotos = {...survey.photos}; delete newPhotos[slot.id]; setSurvey({...survey, photos: newPhotos, score: 0, verdict: ''}); }} className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-all flex items-center justify-center text-white rounded-[1.8rem] backdrop-blur-[2px]"><Trash2 size={24}/></button><div className="absolute top-3 left-3 px-2 py-0.5 bg-black/60 text-white rounded text-[0.45rem] font-black uppercase tracking-widest">{slot.label}</div></>
                   ) : (
                     <><CameraIcon size={24} className="text-gray-300 group-hover:text-primary-500 transition-colors"/><p className="text-[0.6rem] font-black uppercase text-gray-500">{slot.label}</p><input type="file" accept="image/*" className="absolute inset-0 opacity-0 cursor-pointer" onChange={(e) => { const file = e.target.files?.[0]; if (!file) return; const reader = new FileReader(); reader.onload = () => setSurvey(prev => ({ ...prev, photos: { ...prev.photos, [slot.id]: reader.result as string } })); reader.readAsDataURL(file); }} /></>
                   )}
                </div>
             ))}
          </div>
        </div>
        {capturedCount >= 1 && survey.stnk && (
           <div className="space-y-6 pt-4">
              {loading && loadingType === 'SURVEY' ? (
                <div className="glass-card rounded-[3rem] p-12 flex flex-col items-center text-center gap-6 shadow-2xl relative overflow-hidden">
                   <div className="absolute top-0 left-0 w-full h-1 bg-primary-500 animate-scan-fast"></div>
                   <div className="relative"><div className="w-24 h-24 border-4 border-primary-500/20 rounded-full animate-ping opacity-30"></div><div className="absolute inset-0 flex items-center justify-center"><Microscope className="text-primary-500 animate-pulse" size={48} /></div></div>
                   <div className="space-y-2"><p className="text-[0.85rem] font-black uppercase tracking-[0.4em] text-primary-500">Neural Underwriting Active</p><p className="text-[0.55rem] font-bold text-gray-400 uppercase tracking-widest">Scanning Surface Density & Fraud Markers...</p></div>
                </div>
              ) : survey.score > 0 ? (
                <div className="space-y-6 animate-pop-in">
                   <div className={`p-8 rounded-[3.5rem] border-2 shadow-2xl relative overflow-hidden bg-white dark:bg-[#0a0a0a] transition-all duration-500 ${survey.verdict === 'REJECTED' ? 'border-rose-500/30' : survey.score < 60 ? 'border-rose-500/30' : survey.score < 85 ? 'border-amber-500/30' : 'border-primary-500/30'}`}>
                      <div className="absolute top-0 right-0 p-10 opacity-[0.03] pointer-events-none group-hover:scale-110 transition-transform"><BrainCircuit size={200} className="text-primary-500"/></div>
                      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-8 mb-10 relative z-10">
                         <div className="flex items-center gap-8">
                            <div className="relative w-28 h-28 flex items-center justify-center">
                               <svg className="w-full h-full transform -rotate-90">
                                  <circle cx="56" cy="56" r="48" stroke="currentColor" strokeWidth="8" fill="transparent" className="text-gray-100 dark:text-gray-800"/>
                                  <circle cx="56" cy="56" r="48" stroke="currentColor" strokeWidth="8" fill="transparent" strokeDasharray={301.6} strokeDashoffset={301.6 - (301.6 * survey.score) / 100} className={`transition-all duration-[2000ms] ${survey.score >= 85 ? 'text-emerald-500 shadow-[0_0_15px_#10b981]' : survey.score >= 60 ? 'text-amber-500' : 'text-rose-500'}`}/>
                               </svg>
                               <div className="absolute flex flex-col items-center leading-none"><span className="text-3xl font-black">{survey.score}</span><span className="text-[0.5rem] font-bold text-gray-400 uppercase tracking-widest">Score</span></div>
                            </div>
                            <div className="space-y-1"><p className="text-[0.55rem] font-black uppercase text-gray-400 tracking-[0.2em]">Neural Evaluation Index</p><h4 className={`text-4xl font-black uppercase tracking-tighter ${verdictData[survey.verdict]?.color}`}>{verdictData[survey.verdict]?.label}</h4><div className="flex items-center gap-2"><div className={`w-1.5 h-1.5 rounded-full animate-pulse ${survey.verdict === 'CLEAN' ? 'bg-emerald-500' : 'bg-amber-500'}`}></div><span className="text-[0.5rem] font-bold text-gray-400 uppercase tracking-widest">Autonomous Underwriting v5.1</span></div></div>
                         </div>
                         <div className={`px-6 py-4 rounded-3xl ${verdictData[survey.verdict]?.bg} ${verdictData[survey.verdict]?.color} flex items-center gap-4 border border-current border-opacity-10 shadow-lg`}>{survey.verdict && React.createElement(verdictData[survey.verdict]?.icon, {size: 28})}<div className="text-left"><span className="block text-[0.8rem] font-black uppercase tracking-widest leading-none">{survey.verdict === 'CLEAN' ? 'APPROVED' : 'PENDING'}</span><span className="block text-[0.45rem] font-bold uppercase tracking-widest mt-1 opacity-70">Process Link</span></div></div>
                      </div>
                      <div className="p-8 bg-gray-50 dark:bg-white/[0.02] rounded-[2.5rem] border border-black/5 dark:border-white/5 mb-8 relative z-10 shadow-inner group/summary"><div className="flex items-center gap-3 mb-4"><Sparkles size={16} className="text-primary-500 animate-pulse"/><span className="text-[0.6rem] font-black uppercase text-primary-500 tracking-widest">Executive Audit Brief</span></div><p className="text-[0.85rem] font-bold text-gray-700 dark:text-gray-200 italic leading-relaxed">"{survey.summary || verdictData[survey.verdict]?.desc}"</p><div className="absolute top-4 right-6 opacity-10 group-hover/summary:opacity-30 transition-opacity"><Thermometer size={40}/></div></div>
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 relative z-10 mb-8">
                         <div className="p-6 bg-white dark:bg-white/[0.03] border border-black/5 dark:border-white/10 rounded-[3rem] space-y-6 shadow-sm">
                            <div className="flex items-center justify-between border-b border-white/5 pb-4"><div className="flex items-center gap-3"><div className="p-2.5 bg-blue-500/10 text-blue-500 rounded-xl"><Layers size={18}/></div><span className="text-[0.7rem] font-black uppercase tracking-widest">Guideline Matrix</span></div><Badge color="blue">Neural Compliance</Badge></div>
                            <div className="space-y-4">{survey.underwritingChecks?.map((check, i) => (<div key={i} className="flex items-start gap-4 p-3 rounded-2xl hover:bg-white/5 transition-all"><div className={`mt-1 flex-shrink-0 ${check.status === 'PASSED' ? 'text-emerald-500' : check.status === 'WARNING' ? 'text-amber-500' : 'text-rose-500'}`}>{check.status === 'PASSED' ? <CheckCircle size={16}/> : check.status === 'WARNING' ? <AlertTriangle size={16}/> : <ShieldX size={16}/>}</div><div className="flex-1"><p className="text-[0.65rem] font-black uppercase tracking-tight text-gray-800 dark:text-white leading-none">{check.label}</p><p className="text-[0.55rem] font-medium text-gray-500 dark:text-gray-400 mt-1 leading-snug">{check.details}</p></div></div>))}</div>
                         </div>
                         <div className="p-6 bg-white dark:bg-white/[0.03] border border-black/5 dark:border-white/10 rounded-[3rem] space-y-6 shadow-sm">
                            <div className="flex items-center justify-between border-b border-white/5 pb-4"><div className="flex items-center gap-3"><div className="p-2.5 bg-rose-500/10 text-rose-500 rounded-xl"><AlertOctagon size={18}/></div><span className="text-[0.7rem] font-black uppercase tracking-widest">Penalty Log</span></div>{survey.detailedIssues.length > 0 ? (<Badge color="rose">{survey.detailedIssues.length} Anomaly</Badge>) : (<Badge color="emerald">Flawless</Badge>)}</div>
