        <div className="space-y-2">
            <h4 className="text-xl font-black uppercase tracking-tighter">AI Vehicle Survey</h4>
            <p className="text-[0.6rem] font-bold text-gray-500 uppercase tracking-widest max-w-xs mx-auto">Upload 4 sides of your vehicle. Our computer vision will detect pre-existing damage.</p>
        </div>
        <div className="grid grid-cols-2 gap-3">
            {['Front', 'Back', 'Left', 'Right'].map(side => (
                <button key={side} className="aspect-square rounded-2xl bg-white dark:bg-white/5 border-2 border-dashed border-gray-300 dark:border-white/10 flex flex-col items-center justify-center gap-2 hover:border-primary-500 transition-colors">
                    <Camera size={20} className="text-gray-400"/>
                    <span className="text-[0.5rem] font-black uppercase text-gray-400">{side}</span>
                </button>
            ))}
        </div>
        <button onClick={() => setSurveyScore(98)} className="w-full py-4 bg-gray-100 dark:bg-white/10 text-gray-500 dark:text-gray-300 rounded-2xl font-black uppercase text-[0.6rem] tracking-widest hover:bg-primary-500 hover:text-white transition-all">Simulate Scan (Demo)</button>
        {surveyScore && <div className="p-3 bg-emerald-500/10 text-emerald-500 rounded-xl font-black text-xs uppercase tracking-widest border border-emerald-500/20">Vehicle Score: {surveyScore}/100</div>}
    </div>
  );

  const renderStepKYC = () => (
    <div className="space-y-8 animate-fade-in pb-4">
      <div className="p-8 bg-gradient-to-br from-gray-900 to-black rounded-[3rem] border border-white/10 shadow-2xl relative overflow-hidden group">
        <div className="absolute inset-0 bg-primary-500/10 opacity-0 group-hover:opacity-100 transition-opacity duration-1000 blur-3xl"></div>
        <div className="relative z-10 flex items-center gap-6">
          <div className="w-20 h-20 bg-primary-500 rounded-[1.8rem] flex items-center justify-center text-white shadow-2xl shadow-primary-500/30 animate-float">
            <Fingerprint size={40}/>
          </div>
          <div>
            <h4 className="text-2xl font-black text-white uppercase tracking-tighter">Identity Core</h4>
            <p className="text-[0.6rem] font-black text-primary-400 uppercase tracking-[0.4em] mt-1 opacity-80">Secure Enrollment Matrix V3</p>
          </div>
        </div>
        <ScanFace size={120} className="absolute -right-8 -bottom-8 opacity-[0.05] rotate-12 text-white group-hover:scale-110 transition-transform duration-1000"/>
      </div>
      <div className="space-y-6">
        <div className="p-1 bg-gray-100 dark:bg-white/[0.03] rounded-[2rem] border-2 border-black/5 dark:border-white/5 flex flex-col items-center justify-center text-center gap-5 relative py-12 group cursor-pointer transition-all hover:bg-white dark:hover:bg-white/[0.05] hover:border-primary-500/50 overflow-hidden min-h-[220px] shadow-inner">
          {loading && loadingType === 'KTP' ? (<ScannerOverlay label="Neural Identity Mapping" />) : kycData.photo ? (
            <div className="relative w-full h-full p-4 flex flex-col items-center animate-pop-in">
                <div className="relative p-1 bg-white dark:bg-gray-800 rounded-3xl shadow-2xl rotate-1 group-hover:rotate-0 transition-transform duration-500">
                    <img src={kycData.photo} className="max-h-40 rounded-2xl object-contain" alt="KTP Preview" />
                    <button onClick={(e) => { e.stopPropagation(); setKycData({...kycData, photo: null}); setVerifiedFields(new Set()); }} className="absolute -top-3 -right-3 p-2.5 bg-rose-500 text-white rounded-2xl shadow-2xl active:scale-90 transition-all hover:brightness-110"><RefreshCw size={18} className="animate-spin-slow"/></button>
                </div>
                <div className="mt-6 flex items-center gap-3 px-5 py-2 bg-emerald-500/10 text-emerald-500 rounded-full border border-emerald-500/20 shadow-sm animate-pulse"><ShieldCheck size={16}/><p className="text-[0.65rem] font-black uppercase tracking-[0.2em]">Neural Match Verified</p></div>
            </div>
          ) : (
            <>
              <div className="relative">
                <div className="w-20 h-20 bg-white dark:bg-white/[0.03] rounded-[1.8rem] flex items-center justify-center text-gray-300 group-hover:text-primary-500 transition-colors shadow-xl group-hover:scale-110 duration-500"><ImageIcon size={48}/></div>
                <div className="absolute -bottom-2 -right-2 bg-primary-500 text-white rounded-xl p-2 shadow-2xl animate-bounce"><Plus size={18} strokeWidth={4}/></div>
              </div>
              <div className="space-y-1.5">
                <p className="text-[0.8rem] font-black uppercase tracking-[0.2em] text-gray-900 dark:text-white">Upload / Foto KTP Asli</p>
                <p className="text-[0.55rem] font-black text-gray-400 uppercase tracking-widest opacity-60">Gallery or Camera Allowed</p>
              </div>
              <input type="file" accept="image/*" className="absolute inset-0 opacity-0 cursor-pointer" onChange={async (e) => { const file = e.target.files?.[0]; if (!file) return; setLoading(true); setLoadingType('KTP'); const reader = new FileReader(); reader.onload = async () => { const base64 = reader.result as string; setKycData(prev => ({ ...prev, photo: base64 })); const response = await extractKtpData(base64); setLoading(false); setLoadingType(null); if (response.success && response.data) { const newVerified = new Set<string>(); if (response.data.name) newVerified.add('name'); if (response.data.nik) newVerified.add('ktp'); if (response.data.address) newVerified.add('address'); setVerifiedFields(newVerified); setKycData(prev => ({ ...prev, name: response.data.name?.toUpperCase() || prev.name, ktp: response.data.nik || prev.ktp, address: response.data.address?.toUpperCase() || prev.address })); } }; reader.readAsDataURL(file); }} />
            </>
          )}
        </div>
        <div className="grid gap-5">
          <div className="p-8 bg-white dark:bg-white/5 border-2 border-black/5 dark:border-white/5 rounded-[2.5rem] space-y-6 shadow-xl relative overflow-hidden">
            <div className="flex items-center justify-between border-b border-black/5 dark:border-white/5 pb-4">
              <div className="flex items-center gap-4"><UserCheck size={22} className="text-primary-500"/><span className="text-[0.7rem] font-black uppercase tracking-[0.2em] text-gray-400">Registry Intelligence</span></div>
              {verifiedFields.size > 0 && (<div className="flex items-center gap-2 text-emerald-500 animate-pulse bg-emerald-500/10 px-3 py-1 rounded-full border border-emerald-500/20"><Cpu size={12}/><span className="text-[0.55rem] font-black uppercase tracking-widest">Neural Link Sync</span></div>)}
            </div>
            <div className="space-y-5">
              <div className="space-y-2 relative">
                <label className="text-[0.6rem] font-black uppercase text-gray-400 ml-2 tracking-widest">Nama Lengkap</label>
                <div className="relative group">
                    <input placeholder="AHMAD SHOLIHIN" className={`w-full px-6 py-4 rounded-2xl bg-gray-50 dark:bg-black/40 border-2 outline-none focus:border-primary-500 font-black text-sm text-primary-500 uppercase transition-all shadow-inner ${verifiedFields.has('name') ? 'border-emerald-500/30' : 'border-black/5 dark:border-white/5'}`} value={kycData.name} onChange={(e) => setKycData({...kycData, name: e.target.value.toUpperCase()})}/>
                    {verifiedFields.has('name') && (<div className="absolute right-5 top-1/2 -translate-y-1/2 text-emerald-500 drop-shadow-sm animate-pop-in"><CheckCircle2 size={18}/></div>)}
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-[0.6rem] font-black uppercase text-gray-400 ml-2 tracking-widest">Nomor KTP (NIK)</label>
                <div className="relative">
                    <input placeholder="3271XXXXXXXXXXXX" maxLength={16} className={`w-full px-6 py-4 rounded-2xl bg-gray-50 dark:bg-black/40 border-2 outline-none focus:border-primary-500 font-black text-sm text-primary-500 transition-all tracking-[0.3em] shadow-inner ${verifiedFields.has('ktp') ? 'border-emerald-500/30' : 'border-black/5 dark:border-white/5'}`} value={kycData.ktp} onChange={(e) => setKycData({...kycData, ktp: e.target.value.replace(/\D/g, "")})}/>
                    {verifiedFields.has('ktp') && (<div className="absolute right-5 top-1/2 -translate-y-1/2 text-emerald-500 drop-shadow-sm animate-pop-in"><CheckCircle2 size={18}/></div>)}
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-[0.6rem] font-black uppercase text-gray-400 ml-2 tracking-widest">Email</label>
                  <input type="email" placeholder="sholihin@mail.com" className="w-full px-6 py-4 rounded-2xl bg-gray-50 dark:bg-black/40 border-2 border-black/5 dark:border-white/5 outline-none focus:border-primary-500 font-black text-xs text-primary-500 transition-all shadow-inner" value={kycData.email} onChange={(e) => setKycData({...kycData, email: e.target.value})}/>
                </div>
                <div className="space-y-2">
                  <label className="text-[0.6rem] font-black uppercase text-gray-400 ml-2 tracking-widest">No. HP</label>
                  <input placeholder="0812XXXXXXXX" className="w-full px-6 py-4 rounded-2xl bg-gray-50 dark:bg-black/40 border-2 border-black/5 dark:border-white/5 outline-none focus:border-primary-500 font-black text-xs text-primary-500 transition-all shadow-inner" value={kycData.phone} onChange={(e) => setKycData({...kycData, phone: e.target.value.replace(/\D/g, "")})}/>
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-[0.6rem] font-black uppercase text-gray-400 ml-2 tracking-widest">Alamat Domisili</label>
                <div className="relative">
                    <textarea placeholder="JL. RAYA NEURAL NO. 42, JAKARTA SELATAN" rows={3} className={`w-full px-6 py-4 rounded-2xl bg-gray-50 dark:bg-black/40 border-2 outline-none focus:border-primary-500 font-black text-[0.7rem] text-primary-500 uppercase transition-all resize-none shadow-inner leading-relaxed ${verifiedFields.has('address') ? 'border-emerald-500/30' : 'border-black/5 dark:border-white/5'}`} value={kycData.address} onChange={(e) => setKycData({...kycData, address: e.target.value.toUpperCase()})}/>
                    {verifiedFields.has('address') && (<div className="absolute right-5 bottom-5 text-emerald-500 drop-shadow-sm animate-pop-in"><CheckCircle2 size={18}/></div>)}
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );

  const renderStepPayment = () => (
    <div className="space-y-6 animate-fade-in">
        <div className="p-8 bg-white dark:bg-white/5 rounded-[3rem] border-2 border-black/5 space-y-6 shadow-xl relative overflow-hidden">
            <div className="flex justify-between items-start">
                <div><p className="text-[0.5rem] font-black uppercase text-gray-400 tracking-[0.4em]">Final Policy</p><h4 className="text-3xl font-black uppercase tracking-tighter text-primary-500">Auto Matrix</h4></div>
                <div className="p-4 bg-primary-500/10 rounded-2xl text-primary-500 shadow-inner"><Car size={24}/></div>
            </div>
            <div className="border-t border-black/5 pt-6 space-y-3">
                <div className="flex justify-between text-[0.7rem]"><span className="font-bold text-gray-500 uppercase tracking-widest">Vehicle</span><span className="font-black uppercase">{vehicle.brand} {vehicle.model}</span></div>
                <div className="flex justify-between text-[0.7rem]"><span className="font-bold text-gray-500 uppercase tracking-widest">Coverage</span><span className="font-black uppercase">{vehicle.insuranceType}</span></div>
                <div className="flex justify-between text-[0.7rem]"><span className="font-bold text-gray-500 uppercase tracking-widest">Premium</span><span className="font-black text-primary-500">{formatIDR(totalPremium)}</span></div>
            </div>
        </div>
        <button 
            onClick={() => {
                setPayLoading(true);
                setTimeout(() => {
                    savePolicy({
                        type: 'AUTO',
                        holderName: kycData.name || 'USER',
                        holderId: kycData.ktp || 'N/A',
                        premium: totalPremium,
                        details: `${vehicle.brand} ${vehicle.model} - ${vehicle.plate}`
                    });
                    setPayLoading(false);
                    onComplete();
                }, 1500);
            }}
            disabled={payLoading}
            className="w-full py-6 bg-gray-900 dark:bg-white text-white dark:text-black rounded-[2rem] font-black uppercase text-base tracking-[0.25em] shadow-2xl flex items-center justify-center gap-4 transition-all hover:scale-[1.02] active:scale-95"
        >
            {payLoading ? <Loader2 className="animate-spin text-primary-500" size={24}/> : <Wallet size={24} className="text-primary-500"/>}
            {payLoading ? 'PROCESSING...' : 'ACTIVATE POLICY'}
        </button>
    </div>
  );

  return (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-dark-bg text-gray-900 dark:text-white rounded-[3rem] overflow-hidden border border-black/5 shadow-2xl relative">
       <div className="px-8 pt-8 pb-4 bg-white dark:bg-white/5 border-b border-black/5 flex flex-col gap-6 flex-shrink-0">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
               <div className="w-12 h-12 bg-primary-500 rounded-2xl flex items-center justify-center text-white shadow-xl shadow-primary-500/20 group"><Car size={24} className="group-hover:rotate-12 transition-transform"/></div>
               <div><p className="text-[0.45rem] font-black text-gray-400 uppercase tracking-[0.4em] leading-none mb-1">Matrix Auto</p><h3 className="text-lg font-black uppercase tracking-tighter">New Policy</h3></div>
            </div>
            <div className="flex bg-gray-100 dark:bg-white/5 p-1 rounded-xl"><div className="px-3 py-1 text-[0.6rem] font-black text-primary-500 uppercase tracking-widest">{STEPS[step]}</div></div>
          </div>
          <div className="flex gap-2">{STEPS.map((s, i) => (<div key={i} className={`h-1.5 rounded-full flex-1 transition-all duration-500 ${i === step ? 'bg-primary-500 shadow-[0_0_10px_rgba(16,185,129,0.4)]' : i < step ? 'bg-primary-500/30' : 'bg-gray-200 dark:bg-white/10'}`}></div>))}</div>
       </div>
       <div className="flex-1 overflow-y-auto p-8 no-scrollbar">
          {step === 0 && renderStepVehicle()}
          {step === 1 && renderStepCoverage()}
          {step === 2 && renderStepSurvey()}
          {step === 3 && renderStepKYC()}
          {step === 4 && renderStepPayment()}
       </div>
       <div className="px-8 py-6 bg-white dark:bg-[#111] border-t border-black/5 flex items-center justify-between gap-6 flex-shrink-0">
          <div className="flex-1"><p className="text-[0.55rem] font-black uppercase text-gray-400 leading-none mb-1 tracking-widest">Estimate Premium</p><p className="text-2xl font-black tracking-tighter text-primary-500">{formatIDR(totalPremium)}</p></div>
          <div className="flex gap-3">
             {step > 0 && (<button onClick={handleBack} className="p-4 bg-gray-100 dark:bg-white/10 rounded-2xl text-gray-500 hover:text-primary-500 transition-colors"><ChevronLeft size={24}/></button>)}
             {step < STEPS.length - 1 && (<button onClick={handleNext} disabled={(step === 0 && (!vehicle.brand || !vehicle.price)) || (step === 2 && !surveyScore) || (step === 3 && !kycData.name)} className="px-10 py-4 bg-gray-900 dark:bg-white text-white dark:text-black rounded-2xl font-black uppercase text-[0.7rem] tracking-[0.2em] shadow-2xl transition-all active:scale-95 disabled:opacity-30 flex items-center gap-2">Lanjut <ChevronRight size={18}/></button>)}
          </div>
       </div>
    </div>
  );
};

export default CarInsuranceWizard;
